(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0004.js"] = [{"id":"poem-1a2321cf378de3735b97bf09","title":"对月二首 一","author":"张乔","dynasty":"唐","verses":["圆魄上寒空，皆言四海同。","安知千里外，不有雨兼风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-aee4ebe2-0939-4c49-b8bd-d88471711e2a","tags":["中秋节","哲理","月亮"]},{"id":"poem-1a375fe905343cc261eaf648","title":"菩萨蛮·柳花飞处莺声急","author":"牛峤","dynasty":"五代","verses":["柳花飞处莺声急，暗街春色香车立。","金凤小帘开，脸波和恨来。","今宵求梦想，难到青楼上。","赢得一场愁，鸳衾谁并头。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-15","tags":[]},{"id":"poem-1a3ceef7a9e4967e13a465b5","title":"送崔判官还扬子","author":"皎然","dynasty":"唐","verses":["轻传祗远役，依依下姑亭。","秋声满杨柳，暮色绕郊坰。","烟水摇归思，山当楚驿青。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-dc1a9ede-8c1a-4380-9307-a5a5c23e7b01","tags":[]},{"id":"poem-1a49d42de547ab6931f248d0","title":"题凌云寺","author":"司空曙","dynasty":"唐","verses":["春山古寺遶沧波，石磴盘空鸟道过。","百丈金身开翠壁，万龛灯焰隔烟萝。","云生客到侵衣湿，花落僧禅覆地多。","不与方袍同结社，下归尘世竟如何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-225e5b02-b302-47a3-b95f-526b2acd82ac","tags":[]},{"id":"poem-1a4d47897e7e35a2900dfadf","title":"灵岩寺","author":"薛令之","dynasty":"唐","verses":["草堂栖在灵山谷，勤苦诗书向灯烛。","柴门半掩寂无人，惟有白云相伴宿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-8c70f0e2-8df5-42da-975b-927f7093a3d0","tags":[]},{"id":"poem-1a7c32aefaa6815cc1db2334","title":"偈颂（幷序○序为南岳齐己撰） 六十八","author":"居遁","dynasty":"唐","verses":["阎浮有大宝，见少得人稀。","若人将献我，成佛一饷时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c5bb3046-4d16-42ce-aba7-5e1bdfea549d","tags":["衡山"]},{"id":"poem-1a7f5f439437d019939c3123","title":"归国遥·双脸","author":"温庭筠","dynasty":"唐","verses":["双脸，小凤战蓖金飐艳。舞衣无力风敛，藕丝秋色染。","锦帐绣帷斜掩，露珠清晓簟。","粉心黄蕊花靥，黛眉山两点。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-21","tags":[]},{"id":"poem-1a805f795a65cc947fad7cec","title":"陇头行","author":"张籍","dynasty":"唐","verses":["陇头路断人不行，胡骑夜入凉州城。","汉兵处处格鬬死，一朝尽没陇西地。","驱我边人胡中去，散放牛羊食禾黍。","去年中国养子孙，今著毡裘学胡语。","谁能更使李轻车，收取凉州入汉家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d5f74a11-92b2-42b3-b360-0caab73939b3","tags":[]},{"id":"poem-1a8649ddee51c0762cd34220","title":"送乐平苗明府","author":"卢纶","dynasty":"唐","verses":["累职比柴桑，清秋入楚乡。","一船灯照浪，两岸树凝霜。","亭吏趋寒雾，山城敛曙光。","无辞折腰久，仲德在鸳行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a239b10c-5bf9-4567-b4e4-981c1cdccc2f","tags":[]},{"id":"poem-1a8722e2d2eac28a0218a846","title":"洞仙歌·雪云散尽","author":"李元膺","dynasty":"宋","verses":["雪云散尽，放晓晴池院。","杨柳于人便青眼。","更风流多处，一点梅心、相映远。","约略轻笑浅。","一年春好处，不在浓芳，小艳疏香最娇软。","到清明时候，百紫千红花正乱。","已失春风一半。","蚤占取韶光，共追游，但莫管春寒，醉红自暖。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-63","tags":["宋词三百首"]},{"id":"poem-1a87cbfbda686ce7c03e03f3","title":"送晊师","author":"张籍","dynasty":"唐","verses":["九星台下煎茶别，五老峰头觅寺居。","作得新诗旋相寄，人来请莫达空书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-55839370-dff8-405f-a7fa-38486feffa91","tags":[]},{"id":"poem-1a99b3c41e1940800cf6c956","title":"新竹","author":"陆游","dynasty":"宋","verses":["插棘编篱谨护持，养成寒碧映涟漪。","清风掠地秋先到，赤日行天午不知。","解箨时闻声簌簌，放梢初见影离离。","归闲我欲频来此，枕簟仍教到处随。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-新竹","tags":[]},{"id":"poem-1aa04dd319db15741ec86a2d","title":"临江仙·江绕黄陵春庙闲","author":"牛希济","dynasty":"五代","verses":["江绕黄陵春庙闲，娇莺独语关关。","满庭重叠绿苔斑，阴云无事，四散自归山。","箫鼓声稀香烬冷，月娥敛尽弯环。","风流皆道胜人间，须知狂客，拼死为红颜。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-36","tags":[]},{"id":"poem-1aa2808d254b299685fa9598","title":"长歌行","author":"李泌","dynasty":"唐","verses":["天覆吾，地载吾，天地生吾有意无。","不然绝粒升天衢，不然鸣珂游帝都。","焉能不贵复不去，空作昂藏一丈夫。","一丈夫兮一丈夫，千生气志是良图。","请君看取百年事，业就扁舟泛五湖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a85c8e21-b706-4511-aaa4-39447568a11b","tags":[]},{"id":"poem-1aa3621150008f3ab150767b","title":"秘阁郑公移节乡部置酒饯别诗以侑之","author":"张栻","dynasty":"宋","verses":["嗜僻寡同好，意合难语离。","倾盖今几年，盍簪惬心期。","况复王事同，退食陪委蛇。","窥君肺腑中，落落无藩篱。","独有见义勇，褰裳欲从之。","忧时多苦语，怀古更余悲。","坐使岭海间，冰雪映清规。","我拙倚君重，孤怀良自知。","正如乘雾行，不觉蒙其滋。","人生岂无别，念此尤依依。","维闽号蕃庶，今亦困茧丝。","平时里社游，耳目到隠微。","想当入境初，不待褰车帷。","昼绣匪所荣，民瘼要深医。","看培邦本强，讵止乡国肥。","还归报明主，庙论资扶持。","愿坚岁寒节，慰我别离思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-3639f601-77f0-432c-85dc-94032fb4eeb7","tags":[]},{"id":"poem-1aab31852d2c99f734978a5f","title":"郊庙歌辞 享太庙乐章 昭感","author":"不详","dynasty":"唐","verses":["铿锵韶濩，肃穆神容。","洪规赫赫，祠典雍雍。","已周三献，将乘六龙。","虔诚有托，恳志无从。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-bac63ce9-8353-4527-bde9-a8ed8152df49","tags":[]},{"id":"poem-1ab5ae83587d44207683bee6","title":"郊庙歌辞 祭方丘乐章 雍和","author":"褚亮","dynasty":"唐","verses":["柔而能方，直而能敬。","载厚以德，大亨以正。","有涤斯牷，有馨斯盛。","介兹景福，祚我休庆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e817249e-2008-482a-b5b9-b1afeb1fead6","tags":[]},{"id":"poem-1ab6609861714042db68bf34","title":"高邮张生出所得诗画一轴求余作诗因书","author":"华镇","dynasty":"宋","verses":["千岩秀处有扁舟，不驾樵风欲五秋。","金咮未应甘腐鼠，霜翎时自下昆邱。","尘埃漠漠长扃户，云月漫漫独倚楼。","好事古来常恨少，碧霄清思为君搜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-c5329959-9eb4-489f-9f24-81cb816d75c0","tags":[]},{"id":"poem-1ac07bcc2e060f95a3cf0c69","title":"丹霞本老见示拂子并颂次韵","author":"李纲","dynasty":"宋","verses":["钝根不会世间机，且作东山老住持。","有个旄牛闲拂子，用时由我不由伊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f85d7752-97ac-43b9-a363-3874c44f1572","tags":[]},{"id":"poem-1ac32a12019e6c0032e20835","title":"过香积寺","author":"王维","dynasty":"唐","verses":["不知香积寺，数里入云峰。","古木无人径，深山何处钟。","泉声咽危石，日色冷青松。","薄暮空潭曲，安禅制毒龙。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-過香積寺","tags":[]},{"id":"poem-1acd698aeb2af83887a6e23e","title":"迁村居二首 二","author":"李洞","dynasty":"唐","verses":["歌乐听常稀，茅亭静掩扉。","槎来垂钓次，月落问安归。","远客传烧研，幽禽看衲衣。","眼前无俗事，松雨蜀山辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2a6939fb-2fee-4449-b77c-92a68aa8a848","tags":[]},{"id":"poem-1acdf7d3e72411c7af18ede9","title":"生查子·二月到盘洲","author":"洪适","dynasty":"宋","verses":["二月到盘洲，繁缬盈千萼。","恰恰早莺啼，一羽黄金落。","花边自在行，临水还寻壑。","步步肯相随，独有苍梧鹤。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-720","tags":[]},{"id":"poem-1ad93b4fcc2ac7398adf871a","title":"宿郑州","author":"王维","dynasty":"唐","verses":["朝与周人辞，暮投郑人宿。","他乡绝俦侣，孤客亲僮仆。","宛洛望不见，秋霖晦平陆。","田父草际归，村童雨中牧。","主人东臯上，时稼遶茅屋。","虫思机杼悲，雀喧禾黍熟。","明当渡京水，昨晚犹金谷。","此去欲何言，穷边狥微禄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-04ef8f76-9308-42c0-913a-b83cad843362","tags":["抒情","旅途","孤寂","写景"]},{"id":"poem-1af19089da0555eeebcc5689","title":"一丛花·东君密意在花心","author":"晁补之","dynasty":"宋","verses":["东君密意在花心。","飞雪戏妆林。","多情定怪春来晚，故穿花、千点深深。","烟柳上轻，风丝漫袅，楼阁晚还阴。","雕梁双燕悄来音。","帘幕镇沈沈。","西城未有花堪采，醉狂兴、冷落难禁。","应约万红，商量细细，留向未开寻。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-236","tags":[]},{"id":"poem-1af34ccb5a7fbbe5d1c4bf5a","title":"洞仙歌·今春闰好","author":"晁补之","dynasty":"宋","verses":["今春闰好。","怪重阳菊早。","满槛煌煌看霜晓。","唤金钱翠雨，不称标容，潇洒意、陶潜诗中能道。","不应夸绝艳，曾妒春华，因甚东君意不到。","又似锁，三千汉女，偏教明妃、怨西风边草。","也何必、牛山苦沾衣，算只好龙山，醉狂吹帽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-166","tags":[]},{"id":"poem-1afdcbcf4192f8e85f745869","title":"题武陵洞五首 三","author":"曹唐","dynasty":"唐","verses":["却恐重来路不通，殷勤回首谢春风。","白鸡黄犬不将去，且寄桃花深洞中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-75e857c8-8f39-495c-bf82-971bcd6ef3a2","tags":[]},{"id":"poem-1b029fd42852a27f56044fdc","title":"少年游·长安古道马迟迟","author":"柳永","dynasty":"宋","verses":["长安古道马迟迟。","高柳乱蝉栖。","夕阳岛外，秋风原上，目断四天垂。","归云一去无踪迹，何处是前期。","狎兴生疏，酒徒萧索，不似去年时。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-147","tags":["宋词三百首"]},{"id":"poem-1b09ebd9ca1c7efb72c9865d","title":"烛影摇红·老景萧条","author":"毛滂","dynasty":"宋","verses":["老景萧条，送君归去添凄断。","赠君明月满前溪，直到西湖畔。","门掩绿苔应遍。","为黄花、频开醉眼。","橘奴无恙，蝶子相迎，寒窗日短。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-842","tags":["西湖"]},{"id":"poem-1b0cd87cb2a8dabed518eae1","title":"和俞仲素太博游茅山二首 宿明真观","author":"苏颂","dynasty":"宋","verses":["平林行尽到岩扃，一昔恬然道味生。","爽籁远随林谷响，飞云时拂栋梁轻。","闲倾仙斝流琼液，高论神方炼日精。","更想真游成不寐，坐听松韵到黎明。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-fff969f1-ce34-403e-8c3a-daa4c0faf13e","tags":[]},{"id":"poem-1b0e56b7bfa628e7eb435f36","title":"鼓吹曲辞 钓竿篇","author":"沈佺期","dynasty":"唐","verses":["朝日敛红烟，垂竿向绿川。","人疑天上坐，鱼似镜中悬。","避檝时惊透，猜钩每误牵。","湍危不理辖，潭静欲留船。","钓玉君徒尚，征金我未贤。","为看芳饵下，贪得会无全。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8446acb8-23da-451a-958b-120cdfc8b52d","tags":[]},{"id":"poem-1b12504c511911b78cbba259","title":"燕归梁·轻蹑罗鞋掩绛绡","author":"柳永","dynasty":"宋","verses":["轻蹑罗鞋掩绛绡。","传音耗、苦相招。","语声犹颤不成娇。","乍得见、两魂消。","匆匆草草难留恋，还归去又无聊。","若谐雨夕与云朝。","得似个、有嚣嚣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-251","tags":[]},{"id":"poem-1b1658623ef85bdd3aa7f087","title":"送僧二首 二","author":"马戴","dynasty":"唐","verses":["龛中破衲自持行，树下禅床坐一生。","来往白云知岁久，满山猨鸟会经声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3c9a8218-f54a-4008-938c-002aaad1b9fd","tags":[]},{"id":"poem-1b192ad917d718e9baec7518","title":"武陵春·秋染青溪天外水","author":"张先","dynasty":"宋","verses":["秋染青溪天外水，风棹采菱还。","波上逢郎密意传。","语近隔丛莲。","相看忘却归来路，遮日小荷圆。","菱蔓虽多不上船。","心眼在郎边。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-300","tags":[]},{"id":"poem-1b198a30b4fd3d812e315a2a","title":"木兰花","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["鳌头可羡，须知富贵非吾愿。","雁足难凭，没个音书寄此情。","田园荒了，不知松菊犹存否？光景无多，争奈椿萱老去何？自家为父亲所强，来此赴选。","谁知逗留在此，竟然不归？今又复拜皇恩，除为议郎。","虽则任居清要，争奈父母年老，安可久留他乡？天那！知我的父母安否如何？知我的妻室如何看待我的父母？待自家上表辞官，又未知圣意如何？正是：好似和针吞却线，刺人肠肚系人心。","(末丑上唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5005","tags":[]},{"id":"poem-1b2f4f1dd46923b2f27e3682","title":"边游","author":"项斯","dynasty":"唐","verses":["古镇门前去，长安路在东。","天寒明堠火，日晚裂旗风。","塞馆皆无事，儒装亦有弓。","防秋故乡卒，暂喜语音同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-22b58924-a27b-449a-b0fd-9f224646c2e5","tags":[]},{"id":"poem-1b2f75d2926e72fea89e567e","title":"代常州请平江郑侍郎","author":"曾协","dynasty":"宋","verses":["接壤西东似犬牙，一时迎送使君车。","应怜壮岁棠阴在，未觉神京驿路赊。","飞观惯看凉月挂，层楼将见瑞云遮。","当筵莫诉杯行速，两地春光作一家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-ea713b7d-02ca-4337-9f9e-8fafc0260d23","tags":[]},{"id":"poem-1b3902984e7905a622d00361","title":"太白江油尉厅诗","author":"米芾","dynasty":"宋","verses":["岚光深院里，傍砌水泠泠。","野燕巢官舍，溪云入古厅。","日斜孤吏过，帘卷乱峰青。","五色神仙尉，焚香读道经。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-949f7f31-b6f4-48f1-9f34-cfe3dde8b262","tags":[]},{"id":"poem-1b3a4be2e1662d10ca9138ec","title":"积雨辋川庄作","author":"王维","dynasty":"唐","verses":["积雨空林烟火迟，蒸藜炊黍饷东菑。","漠漠水田飞白鹭，阴阴夏木啭黄鹂。","山中习静合朝槿，松下清斋折露葵。","野老与人争席罢，海鸥何事更相疑。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-積雨輞川莊作","tags":[]},{"id":"poem-1b3fed7a9de240a5fbb04f50","title":"小圃即事四首  其三","author":"释居简","dynasty":"宋","verses":["练帨新裁衬缟衣，暝云垂地拥瑶姬。","自知素洁难谐俗，只赴梨花淡月期。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a0617c55-73b5-4848-b01e-38a750fc20be","tags":[]},{"id":"poem-1b45512ed91342e98256e08e","title":"游长宁公主流杯池二十五首 二","author":"上官昭容","dynasty":"唐","verses":["游鲁馆，陟秦台。","汚山壁，媿琼瓌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-39d21a74-e45e-4c99-bd65-40a41a38ed7e","tags":[]},{"id":"poem-1b4648b60cb79d300c45fbb1","title":"次韵许节推喜雨  其二","author":"陈造","dynasty":"宋","verses":["旧雨新雨不后期，丰年当复歌周诗。","手调玉烛属廊庙，归功假手敢固辞。","妇子赴工听晓鼓，山歌和应挥汗雨。","麦黄蚕老十分熟，坐衙日日闻此语。","偕君薄宦群山中，与我忧喜大抵同。","畏垒谬诧庚桑楚，醉乡盍访王无功。","向来小旱烦忧恤，喜雨新来慰衰疾。","焉得妙思作彊对，如埙如箎吕应律。","行藏老矣不问天，一饱肯受儿辈怜。","炉熏频炷窗频托，公余还我文字乐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ca1dd845-d8ee-4c38-bc28-77c2681bef49","tags":[]},{"id":"poem-1b5488786e663c52b34b9eff","title":"寄赠梦英大师","author":"陶谷","dynasty":"宋","verses":["是个碑文念得全，聪明灵性自天然。","离吴别楚三千里，入洛游梁二十年。","负艺已闻喧世界，高眠长见卧云烟。","相逢与我情何厚，问佛方知宿有缘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-dc42e259-567a-4fa6-afb2-9ac24e437316","tags":[]},{"id":"poem-1b576afdc7b303f5a2b344e9","title":"水底鱼","author":"施惠《幽闺记》","dynasty":"元","verses":["(小生、外、末扮番军上)白草黄沙，毡房为住家。","胡儿胡女惯能骑战马。","因贪财宝到中华，闲戏耍，被他拿住，铁里温都哈喇。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2856","tags":[]},{"id":"poem-1b5b1afce0729a59682ca4f4","title":"酬卫八雪中见寄","author":"高适","dynasty":"唐","verses":["季冬忆淇上，落日归山樊。","旧宅带流水，平田临古村。","雪中望来信，醉里开衡门。","果得希代宝，缄之那可论。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c7166837-c70d-4cfd-bf45-baf6930473bf","tags":[]},{"id":"poem-1b6aeccf0b2b5aa577578ccd","title":"送张学士赴西川","author":"徐铉","dynasty":"宋","verses":["右蜀分忧辍近臣，翩翩旄节下青冥。","单车唯载支机石，夙驾长先使者星。","已有清风驰栈道，犹酣别酒过长亭。","佗年报政征黄入，留取文翁旧典刑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-965dc12f-7efc-4c54-a314-28c052fc0843","tags":[]},{"id":"poem-1b736fa36ffba9f46107d3c8","title":"怀张为周朴","author":"贯休","dynasty":"唐","verses":["张周二夫子，诗好人太癖。","更不过岭来，如今头尽白。","人传禹力不到处，河声流向西。","又到处即闭户，逢君方展眉。","不知是不是，若是即大奇。","我又闻二公，心与人不同。","一生常在寂寞中，有时狂吟入僧宅。","锦囊鸟啼荔枝红，有时冥搜海山脑。","珊瑚枝动日杲杲，圣君在上知不知，赤面浊醪许多好。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-08224bf6-bbdb-47b7-b7f8-e002f6199136","tags":[]},{"id":"poem-1b7c3475fd09f222a4c7f7a5","title":"白驹","author":"佚名","dynasty":"先秦","verses":["皎皎白驹，食我场苗。絷之维之，以永今朝。所谓伊人，于焉逍遥？","皎皎白驹，食我场藿。絷之维之，以永今夕。所谓伊人，于焉嘉客？","皎皎白驹，贲然来思。尔公尔侯，逸豫无期？慎尔优游，勉尔遁思。","皎皎白驹，在彼空谷。生刍一束，其人如玉。毋金玉尔音，而有遐心。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-185","tags":[]},{"id":"poem-1b7faf90b84da080dc8ada0a","title":"出山相赞","author":"释了惠","dynasty":"宋","verses":["夜半见明星，山中添冷话。","脚未出山来，此话行天下。","我观一切众生成佛多时，只有你者老子犹欠悟在。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-afbefdc7-3825-4e49-928b-32c74406851e","tags":[]},{"id":"poem-1b87437d78acdb420531545f","title":"三台令·不寐倦长更","author":"李煜","dynasty":"五代","verses":["不寐倦长更，披衣出户行。","月寒秋竹冷，风切夜窗声。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-41","tags":[]},{"id":"poem-1b8ad9238cff2da4e2dd44fe","title":"寄宋使君","author":"贯休","dynasty":"唐","verses":["寺倚乌龙腹，窗中见碧棱。","空廊人画祖，古殿鹤窥灯。","风吼深松雪，炉寒一鼎冰。","唯应谢内史，知此道心澄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-958ba357-f213-43d2-b5c5-da1e222cfabc","tags":[]},{"id":"poem-1b8afcef8bbfa4f58cfc8a25","title":"贺邓璠使君正拜袁州","author":"彭蟾","dynasty":"唐","verses":["六年惠爱及黎甿，大府论功俟陟明。","尺一诏书天上降，二千石禄世间荣。","新添画戟门增峻，旧蹑青云路转平。","更待皇恩醒善政，碧油幢到郡斋迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9852645a-b113-4fe7-bf47-1041aeea01a2","tags":[]},{"id":"poem-1b8d2f7a07e4be373df00878","title":"游仙窟诗 咏双树","author":"张文成","dynasty":"唐","verses":["新华发两树，分香遍一林。","迎风转细影，向日动轻阴。","戏蜂时隐见，飞蝶远追寻。","承闻欲采摘，若个动君心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2893058c-de87-4b31-9753-5ac056a456ec","tags":[]},{"id":"poem-1b97c2611d5e0c9ced477382","title":"玉京秋·烟水阔","author":"周密","dynasty":"宋","verses":["烟水阔。","高林弄残照，晚蜩凄切。","碧砧度韵，银床飘叶。","衣湿桐阴露冷，采凉花、时赋秋雪。","叹轻别。","一襟幽事，砌蛩能说。","客思吟商还怯。","怨歌长、琼壶暗缺。","翠扇恩疏，红衣香褪，翻成消歇。","玉骨西风，恨最恨、闲却新凉时节。","楚箫咽。","谁倚西楼淡月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-95","tags":["宋词三百首"]},{"id":"poem-1b9ced63a45462987f2236a8","title":"别韦参军","author":"高适","dynasty":"唐","verses":["二十解书劒，西游长安城。","举头望君门，屈指取公卿。","国风冲融迈三五，朝廷欢乐弥寰宇。","白璧皆言赐近臣，布衣不得干明主。","归来洛阳无负郭，东过梁宋非吾土。","兔苑为农岁不登，雁池垂钓心长苦。","世人遇我同众人，唯君于我最相亲。","且喜百年有交态，未尝一日辞家贫。","弹棋击筑白日晚，纵酒高歌杨柳春。","欢娱未尽分散去，使我惆怅惊心神。","丈夫不作儿女别，临岐涕泪沾衣巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a03c0482-ee78-47d7-9762-18a156b751af","tags":[]},{"id":"poem-1baa1c6a680349ea389bafec","title":"次韵李似宗见示小圃之作二首  其二","author":"李纲","dynasty":"宋","verses":["竹影桐阴夏日长，水花晚色浄林塘。","招邀风月成三友，邂逅宾朋共一觞。","闲把琴书聊自乐，静看蜂蝶为谁忙。","年来百念皆灰冷，愿学螺川云水乡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-240ba879-b7a7-4a11-871c-b701034a67af","tags":[]},{"id":"poem-1bab6a2b3adf9c2ca6dbe385","title":"黄鸟","author":"佚名","dynasty":"先秦","verses":["黄鸟黄鸟，无集于谷，无啄我粟。此邦之人，不我肯谷。言旋言归，复我邦族。","黄鸟黄鸟，无集于桑，无啄我粱。此邦之人，不可与明。言旋言归，复我诸兄。","黄鸟黄鸟，无集于栩，无啄我黍。此邦之人，不可与处。言旋言归，复我诸父。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-186","tags":[]},{"id":"poem-1bac1aef08385a2e8eabe734","title":"无著对文殊话颂","author":"丽天和尚","dynasty":"唐","verses":["清凉感现圣伽蓝，亲对文殊接话谈。","言下不通好消息，回头祇见翠山嵒。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-19fad08a-6666-4032-9a4c-fdabe23ac7bd","tags":[]},{"id":"poem-1baea98bbd7e641134bdb9cc","title":"天仙子·柳色披衫金缕凤","author":"和凝","dynasty":"五代","verses":["柳色披衫金缕凤，纤手轻拈红豆弄，翠蛾双敛正含情。","桃花洞，瑶台梦，一片春愁谁与共。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-24","tags":[]},{"id":"poem-1baf3e5e71006e71d00ecb01","title":"薄媚衮","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生)因带酒回到后门，一跌疼难忍。","回首看时，瞥见一人，跌倒在草径，呼唤不醒。","忙扶起，血沾手，污我身。","不知何人，杀死他身？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1893","tags":[]},{"id":"poem-1bbba4cc621f54b672da7951","title":"谢杨尚书惠樱桃","author":"卢延让","dynasty":"唐","verses":["满合虚红怕动摇，尚书知重赐樱桃。","揉蓝尚带新鲜叶，泼血犹残旧折条。","万颗真珠轻触破，一团甘露软含消。","春来老病尤珍荷，并食中肠似火烧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-37752376-3872-4130-b9e9-ffaf2c9e6657","tags":[]},{"id":"poem-1bd18c101191838593c0c969","title":"浣溪沙·翠縠参差拂水风","author":"贺铸","dynasty":"宋","verses":["翠縠参差拂水风。","暖云如絮扑低空。","丽人波脸觉春融。","缨挂宝钗初促席，檀高微注玉杯红。","芳醪何似此情浓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-851","tags":[]},{"id":"poem-1bd22b0e8d47e41565090c9e","title":"徐州试反舌无声","author":"张籍","dynasty":"唐","verses":["夏木多好鸟，偏知反舌名。","林幽仍共宿，时过即无声。","竹外天空晓，谿头雨自晴。","居人宜寂寞，深院益凄清。","入雾暗相失，当风闲易惊。","来年上林苑，知尔最先鸣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-35100df3-5470-494b-b237-f5a010690ede","tags":[]},{"id":"poem-1bd87d12cdea1d968ae1a029","title":"观汉水","author":"梁洽","dynasty":"唐","verses":["发源自嶓冢，东注经襄阳。","一道入溟渤，别流为沧浪。","求思咏游女，投吊悲昭王。","水滨不可问，日暮空汤汤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b22bb0c9-e21c-40d4-8aaf-24d3bf78fc49","tags":[]},{"id":"poem-1bdff71575bdf79430496fa0","title":"登楼值雨二首 二","author":"李咸用","dynasty":"唐","verses":["江徼多佳景，秋吟兴未穷。","送来松槛雨，半是蓼花风。","浪猛惊翘鹭，烟昏叫断鸿。","不知今夜客，几处卧鸣篷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f6b573c8-62f4-4b6b-999b-8658ad52a3d9","tags":[]},{"id":"poem-1be31d0c4eb1f7b3ce7e1340","title":"送从弟戴玄往苏州","author":"张籍","dynasty":"唐","verses":["杨柳阊门路，悠悠水岸斜。","乘舟向山寺，着屐到渔家。","夜月红柑树，秋风白藕花。","江天诗景好，回日莫令赊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-95fd9611-2959-4b07-a810-cd374d48c49b","tags":[]},{"id":"poem-1be3b42cf9803a3a55f07359","title":"诉衷情令·郁孤台上立多时","author":"康与之","dynasty":"宋","verses":["郁孤台上立多时。","烟晚暮云低。","山川城郭良是，回首昔人非。","今古事，只堪悲。","此心知。","一尊芳酒，慷慨悲歌，月堕人归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-299","tags":[]},{"id":"poem-1be80f47b658dfcc6b633a0f","title":"和三乡诗","author":"王涤","dynasty":"唐","verses":["浣纱游女出关东，旧迹新词一梦中。","槐陌柳亭何限事，年年回首向春风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-829abc29-6788-44e0-86b8-31e772fe877e","tags":[]},{"id":"poem-1befcc01c6a8232202f23a9e","title":"行路难三首 三","author":"李白","dynasty":"唐","verses":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机雄才岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道。","君不见吴中张翰称达生，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a7b8e17f-ee93-4bdc-a144-b1ba5ab32bb5","tags":["人生","唐诗三百首","乐府","态度"]},{"id":"poem-1bf5fc9693e3e95f2573e2d3","title":"望早日","author":"何景山","dynasty":"唐","verses":["才分天地色，便禁虎狼心。","（见《吟窗杂录》卷十四正字王玄《诗中旨格》）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-bb09632a-a748-4fb8-b1e4-b78a17dc68e1","tags":[]},{"id":"poem-1bf8d5b590c57fa2cd4e0070","title":"水调歌头·江路晓来雨","author":"韩元吉","dynasty":"宋","verses":["江路晓来雨，残暑夜全消。","人言天上今夕，飞鹊渐成桥。","杳杳云车何处。","脉脉红蕖香度。","瓜果趁良宵。","推枕断虹卷，抚槛白鱼跳。","无湖客，临风露，倚兰苕。","云涛四起，极目人世有烟霄。","我送君舟西渡。","君望我帆南浦。","明日恨迢迢。","且醉吴淞月，重听浙江潮。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-827","tags":[]},{"id":"poem-1bfa699d09b4a17f7b50dc1f","title":"病后遇王倚饮赠歌","author":"杜甫","dynasty":"唐","verses":["麟角凤觜世莫识，煎胶续弦奇自见。","尚看王生抱此怀，在于甫也何由羡。","且遇王生慰畴昔，素知贱子甘贫贱。","酷见冻馁不足耻，多病沈年苦无健。","王生怪我颜色恶，荅云伏枕艰难徧。","疟疠三秋孰可忍，寒热百日相交战。","头白眼暗坐有胝，肉黄皮皱命如线。","惟生哀我未平复，为我力致美殽膳。","遣人向市赊香稉，唤妇出房亲自馔。","长安冬葅酸且绿，金城土酥静如练。","兼求富豪且割鲜，密沽斗酒谐终宴。","故人情义晚谁似，令我手脚轻欲漩。","老马为驹信不虚，当时得意况深眷。","但使残年饱吃饭，只愿无事常相见。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a2d1860f-cd55-488c-9c4b-3d19d5b8d3ef","tags":[]},{"id":"poem-1bfecc2cb14d969e2ba6dc98","title":"赠邓郎将四弟","author":"马云奇","dynasty":"唐","verses":["把袂相欢意最浓，十年言笑得朋从。","怜君节操曾无易，只是青山一树松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6b29bf83-e81c-4821-8000-6ba3b18cd626","tags":[]},{"id":"poem-1bffc8206af4a7b3922e1139","title":"卧疾","author":"张籍","dynasty":"唐","verses":["身病始知道，卧读神农经。","空房夜留灯，四壁青荧荧。","羇旅逐人欢，贫贱还自轻。","今来问良医，乃知病所生。","僮仆各相忧，杵臼无停声。","见我形憔悴，劝药语丁宁。","春雨枕席冷，窗前新禽鸣。","开门起无力，遥爱鸡犬行。","服药察耳目，渐觉如酒醒。","方悟养生者，不为忧患并。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e482fbfb-c53a-4202-bde6-410b0cccc84f","tags":[]},{"id":"poem-1c0ab53dee693c3245837853","title":"山有枢","author":"佚名","dynasty":"先秦","verses":["山有枢，隰有榆。子有衣裳，弗曳弗娄。子有车马，弗驰弗驱。宛其死矣，他人是愉。","山有栲，隰有杻。子有廷内，弗洒弗扫。子有钟鼓，弗鼓弗考。宛其死矣，他人是保。","山有漆，隰有栗。子有酒食，何不日鼓瑟？且以喜乐，且以永日。宛其死矣，他人入室。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-114","tags":[]},{"id":"poem-1c0b8b69f4613e324eb6e5da","title":"菩萨蛮·劝君今夜须沉醉","author":"韦庄","dynasty":"五代","verses":["劝君今夜须沉醉，樽前莫话明朝事。","珍重主人心，酒深情亦深。","须愁春漏短，莫诉金杯满。","遇酒且呵呵，人生能几何。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-36","tags":[]},{"id":"poem-1c1dc80c1545c4c49061b702","title":"望江南・忆江南·江南竹","author":"王琪","dynasty":"宋","verses":["江南竹，清润绝纤埃。","深径欲留双凤宿，后庭偏映小桃开。","风月影徘徊。","寒玉瘦，霜霰信相催。","粉泪空流妆点在，羊车曾傍翠枝来。","龙笛莫轻裁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-845","tags":[]},{"id":"poem-1c20b4bf3dbf6cb0b6547831","title":"过马嵬","author":"李益","dynasty":"唐","verses":["汉将如云不直言，寇来翻罪绮罗恩。","托君休洗莲花血，留记千年妾泪痕。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9444dea4-3ec6-4ba6-b571-d569e203670e","tags":[]},{"id":"poem-1c2bfd1bba8ab9c155988bb0","title":"梅子黄时雨","author":"徐田臣《杀狗记》","dynasty":"元","verses":["追想当时，三人共结义，今日里显出乔的。","(旦上)论的亲凶吉事相济，自古及今，已改非从是。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1928","tags":[]},{"id":"poem-1c2dc625590f92d8204eb700","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十一","author":"易静","dynasty":"唐","verses":["三奇墓，课是没（辛本、川本作「设」）人多。","好事中间须减（辛本、川本作「灭」）力，奇门虽（辛本、川本作「须」）遇也难过，固守免蹉跎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-08fde33c-403a-48a9-9a27-f8341bbbd386","tags":[]},{"id":"poem-1c40540b24e0be158915b522","title":"送客还幽州","author":"李益","dynasty":"唐","verses":["惆怅秦城送独归，蓟门云树远依依。","秋来莫射南飞雁，从遣乘春更北飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c5f09de1-23c6-4900-8cfc-c9086e07ae5f","tags":[]},{"id":"poem-1c43aa0c59e7d205a694bf81","title":"泽陂","author":"佚名","dynasty":"先秦","verses":["彼泽之陂，有蒲与荷。有美一人，伤如之何？寤寐无为，涕泗滂沱。","彼泽之陂，有蒲与𫈉。有美一人，硕大且卷。寤寐无为，中心悁悁。","彼泽之陂，有蒲菡萏。有美一人，硕大且俨。寤寐无为，辗转伏枕。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-144","tags":[]},{"id":"poem-1c4477f9ccc89a54fa40c9d3","title":"无题（斯五五五八）一首","author":"佚名","dynasty":"唐","verses":["池台楼观非吾宅，百年还同一宿客；无常忽至即分篱（离），各自东西如路陌。","唯有冤家不相放，罪福前途相执当；冥官依业断形（刑）名，遮莫王公及宰相。","生鬬英雄死论福，贵贩（贱）更无别地狱。","天堂不是选家门，但使回心修作福。","君不见阎浮流转暂时间，何须苦欲求名利；徒劳积业自綊（挟）身，随陷三途觅富贵。","过去王侯数百千，若个久住得长年；良贱有生皆有死，一朝命尽总虚然。","空来空去皈本体，直为迷情不开解。","贪多畏小不知休，总是阿鼻地狱债。","切见愚痴世上人，金（今）生不惜未来身；朝朝暮暮多愁苦，积宝如山犹许（诉）贫。","唯富唯悕（恡）转更贪，子细寻思几许堪；多求积贮蒙辽（缭）乱，死去只得一钱含。","一去冥冥百不知，忽然与世即分离；万物怨（宛）然无一分，唯有善恶并相随。","一切恩情今隔断，何得哭泣相呼唤！生死异路当头行，各自归家更觅伴。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-dee14858-f9c9-4219-ac9b-750a1a109c8a","tags":[]},{"id":"poem-1c45848f78eb75a083fc2058","title":"前腔换头","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["寻思：一怨你死了谁祭祀；二怨你有孩儿，不得他相看顾；三怨你三年，没一个饱暖的日子。","三载相看甘共苦，一朝分别难同死。","(外唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5106","tags":[]},{"id":"poem-1c4826725daaf32c89737b65","title":"一○七","author":"王梵志","dynasty":"唐","verses":["白纸书屏风，客来即与读。","空饭手捻盐，亦胜设酒肉。","（案以上八首并载费衮《梁谿漫志》卷十。","今从知不足斋本录出之。","以上九首除「他人骑大马」一首外，皆见《云溪友议》卷下。","「欺诳得钱君莫羡」一首，《全唐诗续补遗》卷二据《鉴诫录》卷十收录，今删去。","异文录如次：二句「得了却」作「究竟还」，三句作「不信但看槽上驴」，四句「换」作「改」。","）（〖1〗费衮《梁谿漫志》卷十：「山谷以茅季伟事。","亲引梵志『飜袜』之句，人喜道之。","予尝见梵志数颂，词朴而理到，今于此。","其一曰：『欺诳得钱君莫羡。","……』又曰：……」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e75895f4-e2c9-43bd-b4f6-a46834f38975","tags":[]},{"id":"poem-1c4de49ec72599487d127b8b","title":"滴滴金·梅花漏泄春消息","author":"晏殊","dynasty":"宋","verses":["梅花漏泄春消息。","柳丝长，草芽碧。","不觉星霜鬓边白。","念时光堪惜。","兰堂把酒留嘉客。","对离筵，驻行色。","千里音尘便疏隔。","合有人相忆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-548","tags":[]},{"id":"poem-1c4fba84db5d7e0a002c8036","title":"送宣州张员外","author":"徐铉","dynasty":"宋","verses":["故国干戈后，怜君得意归。","绮霞横郡阁，犀烛照渔矶。","天迥青山远，江平白鸟飞。","此行同衣锦，况是老莱衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-57ba0851-6bb0-4f85-97e1-ad3e41f24b83","tags":[]},{"id":"poem-1c625298e7401db92649ff09","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(小生)听禀：祖父同生，念同胞之义，手足之亲。","读书美意，他日显耀门庭。","(背介)思省，岂知哥哥生怒嗔？信谗言教我无投奔。","(净、丑)我每两个为你，劝得口干舌扁，倒说信谗言，难道我每倒是谗言？如今大哥要打自打，不干我事！(小生)将我赶出门，望哥哥息怒，暂且回心。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1714","tags":[]},{"id":"poem-1c642ac77b417496eabe930f","title":"梅径","author":"刘跂","dynasty":"宋","verses":["幸蒙托根地，历历令著行。","莫遣桃李妖，压我玉雪香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-09b32ef5-983b-4cff-97ed-e15ba767b015","tags":[]},{"id":"poem-1c6b3fe71903041f251ce45e","title":"朝中措·慕名人似蚁贪膻","author":"张抡","dynasty":"宋","verses":["慕名人似蚁贪膻。","扰扰几时闲。","输我吴松江上，一帆点破晴烟。","青莎卧月，红鳞荐酒，一醉陶然。","此是人间蓬岛，更于何处求仙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-952","tags":[]},{"id":"poem-1c6d0e1a754d417b1cf382b9","title":"送李补阙归朝","author":"徐凝","dynasty":"唐","verses":["驷马归咸秦，双凫出海门。","还从清切禁，再沐圣明恩。","礼乐中朝贵，文章大雅存。","江湖多放逸，献替欲谁论。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-991d5c5b-acb7-43c9-8389-24e4e32c1c05","tags":[]},{"id":"poem-1c72c282b8c2edc4a19ac4a3","title":"严庆胄射策南归迂途相访六月二十有一日同游城南书院论文鼓琴煮茶烹鲜徘徊湖上薄莫乃归明日作别书此为赠","author":"张栻","dynasty":"宋","verses":["炎暑盛三伏，驾言得清游。","城南才里所，便有山林幽。","崇莲炫平堤，修竹绿高丘。","方兹闵雨辰，亦有清泉流。","举网鲜可食，汲井瓜自浮。","丝桐发妙音，更觉风飕飕。","喜无举业累，独有讲学忧。","逮子闲暇日，微言要穷搜。","譬彼治田者，黾勉在勿休。","但勤穮蔉功，勿作刈获谋。","虽云千里别，岂无置书邮。","祝子时嗣音，慰我日三秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-207bf5a4-f55d-403f-bd7e-a5b10269a1ae","tags":[]},{"id":"poem-1c73f51bc41e69ffbd4470cb","title":"越亭二十韵","author":"元晦","dynasty":"唐","verses":["乏才叨八使，徇禄非三顾。","南服颁诏条，东林证迷误。","未闻述职效，偶脱嚣烦趣。","激水濬㘭塘，缘崖欹磴步。","西岩焕朝旭，深壑囊宿雾。","影气爽衣巾，凉飔轻杖履。","临高神虑寂，远眺川原布。","孤帆逗汀烟，飜鵶集江树。","独探洞府静，怳若偓佺遇。","一瞬契真宗，百年成妄故。","孱颜石户启，杳霭溪云度。","松籁韵宫商，鸳甍势翔溯。","津梁危彴架，济物虚舟渡。","环流驰羽觞，金英妬妆嫮。","笳吟寒垒迥，鸟噪空山暮。","怅望麋鹿心，低回车马路。","悬冠谢陶令，褫珮怀疏傅。","遐想蜕缨緌，徒慙恤襦袴。","福盈祸之倚，权胜道所恶。","何必栖禅关，无言自冥悟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-13045d25-13a5-44a7-a4e9-be6d53718f6e","tags":[]},{"id":"poem-1c772b84d5bab695fde21af3","title":"望远行·欲别无言倚画屏","author":"韦庄","dynasty":"五代","verses":["欲别无言倚画屏，含恨暗伤情。","谢家庭树锦鸡鸣，残月落边城。","人欲别，马频嘶，绿槐千里长堤。","出门芳草路萋萋，云雨别来易东西。","不忍别君后，却入旧香闺。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-49","tags":[]},{"id":"poem-1c7b7beaf1822bbd6c602d64","title":"尾声","author":"施惠《幽闺记》","dynasty":"元","verses":["(外)相逢到此缘非浅，真与假明朝便见。","你二人传语状元，亲事不敢相扳，只请枉临一会，再无他意。","望勿推辞，特请他来赴宴。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3102","tags":[]},{"id":"poem-1c7bcecaef1628853d9071a0","title":"王昭君","author":"崔国辅","dynasty":"唐","verses":["一回望月一回悲，望月月移人不移。","何时得见汉朝使，为妾传书斩画师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-576f5b8e-d99e-43ed-b238-3890abc782c6","tags":[]},{"id":"poem-1c83172e977360633687aee3","title":"昭君怨·深禁好春谁惜","author":"纳兰性德","dynasty":"清","verses":["深禁好春谁惜，薄暮瑶阶伫立。","别院管弦声，不分明。","又是梨花欲谢，绣被春寒今夜。","寂寞锁朱门，梦承恩。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-170","tags":[]},{"id":"poem-1c86ba067d768a6163348876","title":"蓬莱三殿侍宴奉敕咏终南山","author":"杜审言","dynasty":"唐","verses":["北斗挂城边，南山倚殿前。","云标金阙回，树杪玉堂悬。","半岭通佳气，中峰绕瑞烟。","小臣持献寿，长此戴尧天。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-蓬萊三殿侍宴奉敕詠終南山","tags":[]},{"id":"poem-1ca2811fb640f3b19a95dfbf","title":"柏舟","author":"佚名","dynasty":"先秦","verses":["泛彼柏舟，亦泛其流。耿耿不寐，如有隐忧。微我无酒，以敖以游。","我心匪鉴，不可以茹。亦有兄弟，不可以据。薄言往诉，逢彼之怒。","我心匪石，不可转也。我心匪席，不可卷也。威仪棣棣，不可选也。","忧心悄悄，愠于群小。觏闵既多，受侮不少。静言思之，寤辟有摽。","日居月诸，胡迭而微？心之忧矣，如匪浣衣。静言思之，不能奋飞。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-25","tags":[]},{"id":"poem-1ca6a12f24c039e8149e7b35","title":"送别","author":"李咸用","dynasty":"唐","verses":["别意说难尽，离杯深莫辞。","长歌终此席，一笑又何时。","棹入寒潭急，帆当落照迟。","远书如不寄，无以慰相思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4c8b12d5-c287-4152-b546-bde4a09d753b","tags":[]},{"id":"poem-1ca8f77e1062838ef183cc1e","title":"去东林寺诗","author":"曹汾","dynasty":"唐","verses":["峰头不住起孤烟，池上相留有白莲。","尘网分明知束缚，更须骑马别林（「林」字，《金石录补》作「云」。","）泉。","（见《古刻丛钞》。","以《槐卢丛书》本《金石录补》参校之。","）（〖1〗诗下原署「会昌三年七月十三日秘书省正字曹汾题」十七字。","〖2〗陶宗仪《古刻丛钞》：此诗在昙玭碑阴，尘土昏塞，无知之者。","至和三年春二月，陈国袁陟来游山，徧抉奇迹，始发其晦。","东林诗多矣，未有如此篇之意远而美者，因题以永之。","汾，开成四年崔蠡下进士，后为中书舍人，户部侍郎、忠武军节度使，实丞相确之弟也。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e67dff8d-2d70-42c5-bc37-069447d85006","tags":[]},{"id":"poem-1cab2d7bcf1ca57c42a2e3e6","title":"巫山一段云·有客经巫峡","author":"李珣","dynasty":"五代","verses":["有客经巫峡，停桡向水湄。","楚王曾此梦瑶姬，一梦杳无期。","尘暗珠帘卷，香消翠帷垂。","西风回首不胜悲，暮雨洒空祠。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-21","tags":[]},{"id":"poem-1cb0a10c9aadf3daa4be7063","title":"长亭怨慢·渐吹尽、枝头香絮","author":"姜夔","dynasty":"宋","verses":["渐吹尽、枝头香絮。","是处人家，绿深门户。","远浦萦回，暮帆零乱向何许。","阅人多矣，谁得似、长亭树。","树若有情时，不会得、青青如此。","日暮。","望高城不见，只见乱山无数。","韦郎去也，怎忘得、玉环分付。","第一是、早早归来，怕红萼、无人为主。","算空有并刀，难翦离愁千缕。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-133","tags":["宋词三百首"]},{"id":"poem-1cd9d81a6db77b1aefc6cd54","title":"寄左先辈","author":"谭用之","dynasty":"宋","verses":["狂歌白鹿上青天，可似兰塘钓紫烟。","万卷祖龙坑外物，一泓孙楚耳中泉。","翩翾蛮榼薰晴浦，毂辘鱼车响夜船。","学取青莲李居士，一生杯酒在神仙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-3a435387-3c07-4cd8-ba2d-5c883598604e","tags":[]},{"id":"poem-1cda3777c0835c72a3c39faf","title":"采桑","author":"王建","dynasty":"唐","verses":["鸟鸣桑叶间，绿条复柔柔。","攀看去手近，放下长长钩。","黄花盖野田，白马少年游。","所念岂回顾，良人在高楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-74b26b8b-be15-482f-a6b0-0135133c917f","tags":[]},{"id":"poem-1ce0388e8feb4b413b799525","title":"废瑟词","author":"张籍","dynasty":"唐","verses":["古瑟在匣谁复识，玉柱颠倒朱丝黑。","千年曲谱不分明，乐府无人传正声。","秋虫暗穿尘作色，腹中不辨工人名。","几时天下复古乐，此瑟还奏云门曲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1fa1686d-4d76-4113-9758-3dd042a3c36a","tags":[]},{"id":"poem-1ce9d41e4bcc90358e1bb776","title":"两同心·巍巍剑外","author":"杜安世","dynasty":"宋","verses":["巍巍剑外，寒霜覆林枝。","望衰柳、尚色依依。","暮天静、雁阵高飞。","入碧云际。","江山秋色，遣客心悲。","蜀道巇崄行迟。","瞻京都迢递。","听巴峡、数声猿啼。","惟独个、未有归计。","谩空怅望，每每无言，独对斜晖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-869","tags":[]},{"id":"poem-1cea02b718b8a7f11ebd91d9","title":"二七","author":"王梵志","dynasty":"唐","verses":["坐见人来起，尊亲尽远迎。","无论贫与富，一概惣须平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-50614bd2-a7ca-4f3c-b421-65ad0af0dc63","tags":[]},{"id":"poem-1cef07e22c5254e62a1f69cb","title":"哭亦周  其四","author":"赵文","dynasty":"宋","verses":["二十年来黍一炊，英风惟有冢累累。","儿童踯躅牛羊戏，陌上行人谓此谁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-39b66f97-d1bb-41bc-9a71-089288dc62db","tags":[]},{"id":"poem-1cfb6f51d144e1ca714bf8cd","title":"夏日闲居","author":"张籍","dynasty":"唐","verses":["无事门多闭，偏知夏日长。","早蝉声寂寞，新竹气清凉。","闲对临书案，看移晒药床。","自怜归未得，犹寄在班行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3e458cb0-2f60-4831-8ccd-049b303ad609","tags":[]},{"id":"poem-1d002cc41d90c65b98cb680f","title":"颂古三十一首  其二六","author":"释安永","dynasty":"宋","verses":["独向沧溟截众流，等闲舞棹掷金钩。","白云不露烟波阔，横笛一声天地秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c876f7e4-7e8b-4d11-8651-f0f0a16a29d3","tags":[]},{"id":"poem-1d0c92b0344498f9e2f87818","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［丑］呆蠢丫头，出语污人耳。","恁推三阻四，话不投机。","豪家求汝效于飞，他有甚相亏？出言抵撞，你好没尊卑。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8087","tags":[]},{"id":"poem-1d0ccf3b0441fb0488979709","title":"同庄秀才宿镇星观","author":"马戴","dynasty":"唐","verses":["的的星河落，沾苔复洒松。","湿光微泛草，石翠澹摇峰。","野观云和月，秋城漏间钟。","知君亲此境，九陌少相逢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3d907ab0-fa98-4704-aa08-7eca8c296e99","tags":[]},{"id":"poem-1d1704806b93c90f78edac91","title":"虞美人·芙蓉池畔都开遍","author":"曾觌","dynasty":"宋","verses":["芙蓉池畔都开遍。","又是西风晚。","霁天碧净暝云收。","渐看一轮冰魄、冷悬秋。","闽山层叠迷归路。","把酒宽愁绪。","旧欢新恨几凄凉。","暗想瀛洲何处、梦悠扬。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-395","tags":[]},{"id":"poem-1d1e61f6377ec095d6618f5f","title":"醉公子·暮烟笼藓砌","author":"尹鹗 六首","dynasty":"五代","verses":["暮烟笼藓砌，戟门犹未闭。","尽日醉寻春，归来月满身。","离鞍偎绣袂，坠巾花乱缀。","何处恼佳人，檀痕衣上新。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-31","tags":[]},{"id":"poem-1d21cf0110992e86e68031f6","title":"嵩山十志十首 其八","author":"卢鸿一","dynasty":"唐","verses":["青崖阴兮月磵曲，重幽叠邃兮隐沦躅。","草树緜幂兮翠蒙茏，当其无兮庭在中。","当无有用兮幂翠庭，神可谷兮道可冥。","有幽人兮张素琴，皇徽兮绿水阴，德之愔兮澹多心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4699c6a4-e9cb-4315-85ae-882145bdc345","tags":[]},{"id":"poem-1d28e88d92a829502240d6e7","title":"将入匡山别芳昼二公二首 一","author":"贯休","dynasty":"唐","verses":["喷岚堆黛塞寒碧，窗前古雪入白石。","临岐约我来不来，若来须拨红霞觅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c68e9289-7c74-449f-ac83-6f8924d8b848","tags":["庐山"]},{"id":"poem-1d2ef30777f11bcbe9e7899e","title":"升平词五首 五","author":"曹唐","dynasty":"唐","verses":["五帝三皇主，萧曹魏邴臣。","文章唯返朴，戈甲尽生尘。","谏纸应无用，朝纲自有伦。","升平不可记，所见是闲人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-75f8b040-292d-4630-ae51-86b5365e6b38","tags":[]},{"id":"poem-1d3faeed2ad9166d10cc21b0","title":"横吹曲辞 后出塞五首 三","author":"杜甫","dynasty":"唐","verses":["古人重守边，今人重高勋。","岂知英雄主，出师亘长云。","六合已一家，四夷且孤军。","遂使貔虎士，奋身勇所闻。","拔劒击大荒，日牧胡马群。","誓开玄冥北，持以奉吾君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-dffcc914-3b19-401d-963b-59c75a017857","tags":[]},{"id":"poem-1d4410ac17c55b41cfe52b96","title":"小游仙诗九十八首 二十六","author":"曹唐","dynasty":"唐","verses":["偷来洞口访刘君，缓步轻擡玉线裙。","细擘桃花逐流水，更无言语倚彤云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f138f395-d02f-423f-a9a8-f009e4dac3c5","tags":[]},{"id":"poem-1d48ac3964c558ed2c3fa59c","title":"贫家壁","author":"李善宁之子","dynasty":"唐","verses":["椒气从何得？灯光凿处分。","拖筵来藻饰，惟有篆愁君。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-96df7153-0acf-4043-8b28-4524234c2eb3","tags":[]},{"id":"poem-1d4bd1ea14233c66f0be2af9","title":"与卢象集朱家","author":"王维","dynasty":"唐","verses":["主人能爱客，终日有逢迎。","贳得新丰酒，复闻秦女筝。","柳条疎客舍，槐叶下秋城。","语笑且为乐，吾将达此生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7a527e41-ccaf-442c-98ea-99ab9b11a3bf","tags":[]},{"id":"poem-1d4f376a4d1af5ae423a5488","title":"泊港口","author":"释居简","dynasty":"宋","verses":["港阔风初霁，潮平夜欲分。","半江都是月，一点不留云。","东去舟无数，南飞鹊恋群。","疎钟何处寺，隔浦最先闻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-fa1f63ce-cf74-4a5e-99d2-12a90e5d6cbd","tags":[]},{"id":"poem-1d520a2f8475f028a2e93e11","title":"饮茶歌诮崔石使君","author":"皎然","dynasty":"唐","verses":["越人遗我剡溪茗，采得金牙爨金鼎。","素瓷雪色缥沫香，何似诸仙琼蘂浆。","一饮涤昏寐，情来朗爽满天地。","再饮清我神，忽如飞雨洒轻尘。","三饮便得道，何须苦心破烦恼。","此物清高世莫知，世人饮酒多自欺。","愁看毕卓瓮间夜，笑向陶潜篱下时。","崔侯啜之意不已，狂歌一曲惊人耳。","孰知茶道全尔真，唯有丹丘得如此。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-41fca742-a88c-4a20-8dfe-a48d2d6f7d43","tags":[]},{"id":"poem-1d5f5294a27cb4ca6410b6ef","title":"赠识古法师","author":"栖白","dynasty":"唐","verses":["重城深寺讲初休，却忆家山访旧游。","对月与君相送夜，闻蛩教我独惊秋。","云心杳杳难为别，鹤性萧萧不可留。","遥想孤舟清渭上，飘然帆影起离愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9917ad6d-e7f7-419f-a007-0ecdd72a859a","tags":[]},{"id":"poem-1d65b2f578388c9759bcce37","title":"·","author":"徐台符","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a05d43e7-48a3-44f2-93a2-2abfcf77124e","tags":[]},{"id":"poem-1d6c273f188a95b86f548ec2","title":"舂陵登望","author":"皎然","dynasty":"唐","verses":["西底空流水，东垣但聚云。","最伤梅岭望，花雪正纷纷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2fb49477-b27a-4765-8627-9a4684b7a23f","tags":[]},{"id":"poem-1d7126befb72b8293570f8a6","title":"与高适薛据慈恩寺浮图","author":"岑参","dynasty":"唐","verses":["塔势如涌出，孤高耸天宫。","登临出世界，磴道盘虚空。","突兀压神州，峥嵘如鬼工。","四角碍白日，七层摩苍穹。","下窥指高鸟，俯听闻惊风。","连山若波涛，奔凑似朝东。","青槐夹驰道，宫馆何玲珑。","秋色从西来，苍然满关中。","五陵北原上，万古青蒙蒙。","净理了可悟，胜因夙所宗。","誓将挂冠去，觉道资无穷。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-93d82a12-5e4d-45c2-b837-d0c54447fba3","tags":["唐诗三百首","五言古诗","景点","写景","忧思","写塔"]},{"id":"poem-1d823ba944a64d106d3bc3f1","title":"故陈州刺史赠兵部尚书韦公挽词","author":"孙逖","dynasty":"唐","verses":["奕叶金章贵，连枝鼎位尊。","台庭为凤穴，相府是鸰原。","世阅空悲命，泉幽不返魂。","惟余汉臣史，继术赞韦门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c408c2f1-63a3-41f0-8685-70aee6c960b0","tags":[]},{"id":"poem-1d8274bb69aed7d46ce3696f","title":"郊庙歌辞 五郊乐章 送神","author":"不详","dynasty":"唐","verses":["春末冬暮，徂夏杪秋。","土王四月，时季一周。","黍稷已享，笾豆宜收。","送神有乐，神其赐休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8cd434d7-67ab-4501-8aac-e4a5e8b12dd2","tags":[]},{"id":"poem-1d8e38c093a985bca2da1247","title":"拂舞歌辞","author":"李贺","dynasty":"唐","verses":["吴娥声绝天，空云闲裴回。","门外满车马，亦须生绿苔。","尊有乌程酒，劝君千万寿。","全胜汉武锦楼上，晓望晴寒饮花露。","东方日不破，天光无老时。","丹成作蛇乘白雾，千年重化玉井土。","从蛇作土一千载，吴堤绿草年年在。","背有八卦称神仙，邪鳞顽甲滑腥涎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9815b2df-26e7-4efc-ab90-c4efbe1deffc","tags":[]},{"id":"poem-1d93493f368177bc91787441","title":"寄题云门寺梵月无侧房","author":"皎然","dynasty":"唐","verses":["越山千万云门绝，西僧貌古还名月。","清朝扫石行道归，林下眠禅看松雪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-bc174219-f611-4024-8870-625b9f426ea5","tags":[]},{"id":"poem-1d9c4f83003eb6eaee4b925f","title":"读东坡和渊明贫士诗寄诸子姪云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁谿诸弟以发数千里一笑  其二","author":"李纲","dynasty":"宋","verses":["凄凉寓僧舍，寂寞坐松轩。","虽辞万锺禄，尚未自灌园。","仲尼犹在陈，我厨晨有烟。","藜羮得一饱，滴露味自研。","寒窗写周易，更咏五千言。","儒生真可笑，饿隐称其贤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-0ff87c7a-20d7-4fbf-bd7f-ae7c8a111990","tags":[]},{"id":"poem-1db2c3b16f4a20bcc1bc675d","title":"澡兰香·盘丝系腕","author":"吴文英","dynasty":"宋","verses":["盘丝系腕，巧篆垂簪，玉隐绀纱睡觉。","银瓶露井，彩云窗，往事少年依约。","为当时、曾写榴裙，伤心红绡褪萼。","黍梦光阴渐老，汀洲烟箬。","莫唱江南古调，怨抑难招，楚江沈魄。","薰风燕乳，暗雨梅黄，午镜澡兰帘幕。","念秦楼、也拟人归，应翦菖浦自酌。","但怅望、一屡新蟾，随人天角。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-197","tags":["宋词三百首"]},{"id":"poem-1db8628fc2d3f34ee5a4818c","title":"玉楼春·寂寂画堂梁上燕","author":"魏承班","dynasty":"五代","verses":["寂寂画堂梁上燕，高卷翠帘横数扇。","一庭春色恼人来，满地落花红几片。","愁倚锦屏低雪面，泪滴绣罗金缕线。","好天凉月尽伤心，为是玉郎长不见。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-2","tags":[]},{"id":"poem-1dc2857d08b2593724d52c78","title":"对镜吟","author":"长孙佐辅","dynasty":"唐","verses":["忆昔逢君新纳娉，青铜铸出千年镜。","意怜光彩固无瑕，义比恩情永相映。","每将鉴面兼鉴心，鉴来不辍情逾深。","君非结心空结带，结处尚新恩已背。","开帘览镜悲难语，对面相看孟门阻。","掩匣徒慙双凤飞，悬台欲效孤鸾舞。","昔日照来人共许，今朝照罢自生疑。","镜上有尘犹可淬，君恩讵肯无回时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0e2d1361-03c5-444c-ab51-166201d23d35","tags":[]},{"id":"poem-1dc4ffa334785942b24f1932","title":"小游仙诗九十八首 三十四","author":"曹唐","dynasty":"唐","verses":["天上邀来不肯来，人间双鹤又空回。","秦皇汉武死何处，海畔红桑花自开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a101806a-f602-46be-ac4f-c06fd32c72cd","tags":[]},{"id":"poem-1dcc98a43372d71cd140fce7","title":"登楼","author":"杜甫","dynasty":"唐","verses":["花近高楼伤客心，万方多难此登临。","锦江春色来天地，玉垒浮云变古今。","北极朝廷终不改，西山寇盗莫相侵。","可怜后主还祠庙，日暮聊为梁甫吟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-12919986-2d09-4d2e-b5ad-f2485e40ada5","tags":["唐诗三百首","隋・唐・五代","七言律诗","写景","怀古","一年级下册","忧国忧民","感时","初中古诗","高中古诗","九年级下册(课外)"]},{"id":"poem-1ddb612714d68af5bf25686d","title":"晚凉","author":"宋伯仁","dynasty":"宋","verses":["两两蝉声送夕阳，竹阴移绿上藤床。","黄昏急雨无多子，喜得今宵梦亦凉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-e9f58779-a309-4ba3-909c-3748ca714ff1","tags":[]},{"id":"poem-1ddec73a46bcce9df789c374","title":"郊庙歌辞 享节愍太子庙乐章 登歌酌鬯","author":"不详","dynasty":"唐","verses":["灼灼重明，仰承元首。","既贤且哲，惟孝与友。","惟孝虽遥，灵规不朽。","礼因诚致，备絜玄酒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-79ddee12-c5fd-4c8d-a46b-eb1d6649d850","tags":[]},{"id":"poem-1ddf01326aa55a75c60f5ed5","title":"九日送人","author":"司空曙","dynasty":"唐","verses":["送人冠獬豸，值节佩茱萸。","均覆征三壤，登车出五湖。","水风凄落日，岸叶飒衰芜。","自恨尘中使，何因在路隅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-402a706d-4568-471e-ac1f-e01a7f90f6cf","tags":[]},{"id":"poem-1de692f947d76e137078b2bc","title":"人娇·当日相逢","author":"柳永","dynasty":"宋","verses":["当日相逢，便有怜才深意。","歌筵罢、偶同鸳被。","别来光景，看看经岁。","昨夜里、方把旧欢重继。","晓月将沈，征骖已鞴。","愁肠乱、又还分袂。","良辰好景，恨浮名牵系。","无分得、与你恣情浓睡。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-142","tags":[]},{"id":"poem-1dec8946acf8f81552d8b5b1","title":"遥伤茅山县孙尊师三首 三","author":"李德裕","dynasty":"唐","verses":["空宇留丹灶，层霞被羽衣。","旧山闻鹿化，遗舃尚凫飞。","数日奇香在，何年白鹤归。","想君旋下泪，方欵里闾扉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-11f38d5e-78f2-42cb-aaff-a5146e980d4d","tags":[]},{"id":"poem-1df0aaccf477efba126afb14","title":"岁晏行","author":"杜甫","dynasty":"唐","verses":["岁云暮矣多北风，潇湘洞庭白雪中。","渔父天寒网罟冻，莫徭射雁鸣桑弓。","去年米贵阙军食，今年米贱大伤农。","高马达官厌酒肉，此辈杼轴茅茨空。","楚人重鱼不重鸟，汝休枉杀南飞鸿。","况闻处处鬻男女，割慈忍爱还租庸。","往日用钱捉私铸，今许铅锡和青铜。","刻泥为之最易得，好恶不合长相蒙。","万国城头吹画角，此曲哀怨何时终。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1a285196-1fe5-4d28-9ba1-dd75e9ce0af2","tags":["洞庭湖","忧国忧民","冬天"]},{"id":"poem-1df81586955e63d6cf24cdd0","title":"香柳娘","author":"萧德祥《小孙屠》","dynasty":"元","verses":["想哥哥那里，你还知么，兄弟在此身亡化？黄泉无旅店，今夜宿谁家？一命掩黄沙。","我如今挣？，将拄仗按拿，魂飞魄讶。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8676","tags":[]},{"id":"poem-1e08514475a8efca8652000a","title":"一丛花令・一丛花·伤高怀远几时穷","author":"张先","dynasty":"宋","verses":["伤高怀远几时穷。","无物似情浓。","离愁正引千丝乱，更东陌、飞絮。","嘶骑渐遥，征尘不断，何处认郎踪。","双鸳池沼水溶溶。","南北小桡通。","梯横画阁黄昏后，又还是、斜月帘栊。","沈恨细思，不如桃杏，犹解嫁东风。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-155","tags":["宋词三百首"]},{"id":"poem-1e09f9424695eb854607cb65","title":"忆故山赠司空曙","author":"李端","dynasty":"唐","verses":["汉主金门正召才，马卿多病自迟回。","旧山𫏐别老将至，芳草欲阑归去来。","云在高天风会起，年如流水日长催。","知君素有栖禅意，岁晏蓬门迟尔开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-855456e2-f8a8-4344-b207-b764395bda19","tags":[]},{"id":"poem-1e0d2e43d93b1a3e4d76f0d9","title":"鹊桥仙·北窗凉透","author":"张孝祥","dynasty":"宋","verses":["北窗凉透，南窗月上，浴罢满怀风露。","不知何处有花来，但怪底、清香无数。","炎州珍产，吴儿未识，天与幽芳独步。","冰肌玉骨岁寒时，倩间止、堂中留住。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-251","tags":[]},{"id":"poem-1e114f5ba4f36c8b93933314","title":"送三藏归西天国","author":"李洞","dynasty":"唐","verses":["十万里程多少碛，沙中弹舌授降龙。","五天到日应头白，月落长安半夜钟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3c89f910-3c30-4728-b5d6-48b2bf980932","tags":[]},{"id":"poem-1e2734802ad6c11f6c27b8ed","title":"别张赞","author":"司空曙","dynasty":"唐","verses":["今日山晴后，残蝉菊发时。","登楼见秋色，何处最相思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1f73ad47-4dc9-4422-83fd-04a6600e0328","tags":[]},{"id":"poem-1e378ad3a4b7144dc960f669","title":"浣溪沙·漠漠新田绿未齐","author":"蔡伸","dynasty":"宋","verses":["漠漠新田绿未齐。","柳阴阴下水平堤。","竹间时有乳鸦啼。","云敛屏山横枕畔，夜阑璧月转林西。","玉芝香里彩鸳栖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-951","tags":[]},{"id":"poem-1e3cccac05bbc55e1fe9df09","title":"拜宣武军节度使","author":"李绅","dynasty":"唐","verses":["油幢竝入虎旗开，锦橐从天凤诏来。","星应魏师新鼓角，地嫌梁苑旧池台。","日晖红斾分如电，人拥青门动若雷。","伊洛镜清回首处，是非纷杂任尘埃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-c19415dc-5337-4280-897b-67965cc47d1b","tags":[]},{"id":"poem-1e3cea34b791799fed486067","title":"菊磵卜居","author":"释居简","dynasty":"宋","verses":["王师且愿休，小为蕺山留。","五月凉时过，千岩胜处游。","子耕无父业，弟唱有兄酬。","好在牛腰轴，丁宁莫暗投。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8c98c886-9a08-485b-b1dc-532dee0b446c","tags":[]},{"id":"poem-1e42097fcb08ac9b8bc35668","title":"小弁","author":"佚名","dynasty":"先秦","verses":["弁彼鸴斯，归飞提提。民莫不谷，我独于罹。何辜于天？我罪伊何？心之忧矣，云如之何？","踧踧周道，鞫为茂草。我心忧伤，惄焉如捣。假寐永叹，维忧用老。心之忧矣，疢如疾首。","维桑与梓，必恭敬止。靡瞻匪父，靡依匪母。不属于毛？不罹于里？天之生我，我辰安在？","菀彼柳斯，鸣蜩嘒嘒，有漼者渊，萑苇淠淠。譬彼舟流，不知所届，心之忧矣，不遑假寐。","鹿斯之奔，维足伎伎。雉之朝雊，尚求其雌。譬彼坏木，疾用无枝。心之忧矣，宁莫之知？","相彼投兔，尚或先之。行有死人，尚或墐之。君子秉心，维其忍之。心之忧矣，涕既陨之。","君子信谗，如或酬之。君子不惠，不舒究之。伐木掎矣，析薪扡矣。舍彼有罪，予之佗矣。","莫高匪山，莫浚匪泉。君子无易由言，耳属于垣。无逝我梁，无发我笱。我躬不阅，遑恤我后。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-196","tags":[]},{"id":"poem-1e46a4848b5ee94b2f42b464","title":"寻西山隐者不遇","author":"丘为","dynasty":"唐","verses":["绝顶一茅茨，直[上]三十里。","扣关无僮仆，窥室唯案几。","若非巾柴车，应是钓秋水。","差池不相见，黾勉空仰止。","草色新雨中，松声晚牕里。","及兹契幽绝，自足荡心耳。","虽无宾主意，颇得清净理。","兴尽方下山，何必待之子。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-10a0aedc-4b39-494b-a36c-28c6df28a668","tags":["唐诗三百首","五言古诗","友情"]},{"id":"poem-1e475c785fdc6e4b77aa087a","title":"冬夜与蔡校书宿无可上人院","author":"刘得仁","dynasty":"唐","verses":["儒释偶同宿，夜窗寒更清。","忘机于世久，晤语到天明。","月倒高松影，风旋一磬声。","真门犹是幻，不用觉浮生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-785c49d3-7be0-4b4d-a7ea-6175a4d58ea2","tags":[]},{"id":"poem-1e47eea11d77078979037c9e","title":"寻仙","author":"张籍","dynasty":"唐","verses":["溪头一径入青崖，处处仙居隔杏花。","更见峰西幽客说，云中犹有两三家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2f0e76c3-fa01-4082-b01c-3a1193ff7e06","tags":[]},{"id":"poem-1e488ed631d7113519df7a42","title":"山居诗  其四八","author":"释延寿","dynasty":"宋","verses":["高才宏略气凌云，世上浮名梦里身。","苏氏谩称降六国，韩公休说卷三秦。","当朝虽立千年事，古庙唯存一聚尘。","毕竟思量浑大错，何如林下养天真。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-aada7b9c-bf35-4f20-b8a3-e3357b8426f4","tags":[]},{"id":"poem-1e4bfd937243fe651ce33e29","title":"夏（原作「冬」）日野望","author":"佚名","dynasty":"唐","verses":["出户过河梁，登高试望乡。","云随愁处断，川逐思弥长。","晚吹低藂草，遥山落夕阳。","徘徊噎不语，空使泪沾裳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-02ea8feb-8f55-47be-8d65-33ea4bd8d76b","tags":[]},{"id":"poem-1e4c068f71d0f2d09e91a4aa","title":"南乡子·裹帽拈吟须","author":"李石","dynasty":"宋","verses":["裹帽拈吟须。","我是蓬莱旧酒徒。","除了茅君谁是伴，麻姑。","洞里仙浆不用沽。","弱水渺江湖。","醉里笙歌醉里扶。","纵饮菊潭餐菊蕊，茱萸。","医得人间瘦也无。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-273","tags":[]},{"id":"poem-1e51ec495ac4abc3c8fbe89c","title":"送杨少尹赴凤翔","author":"张籍","dynasty":"唐","verses":["诗名往日动长安，首首人家卷里看。","西学已行秦博士，南宫新拜汉郎官。","得钱祗了还书铺，借宅常时事药栏。","今去岐州生计薄，移居偏近陇头寒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7670129d-e5f8-483d-9c00-361f0e425faa","tags":[]},{"id":"poem-1e5802928b1c607fc003e829","title":"宫词  其九八","author":"张公庠","dynasty":"宋","verses":["自匀轻黛怯春寒，巧画双眉称绿鬟。","楼上远山随指见，槛中新月对人弯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-020cd2b9-1179-403e-b733-7e2876c31432","tags":[]},{"id":"poem-1e592e30664e1e3ac2f95def","title":"浣溪沙·已是人间不系舟","author":"张孝祥","dynasty":"宋","verses":["已是人间不系舟。","此心元自不惊鸥。","卧看骇浪与天浮。","对月只应频举酒，临风何必更搔头。","暝烟多处是神州。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-285","tags":[]},{"id":"poem-1e5d9ce8906593afac7b12f3","title":"夜吟","author":"李山甫","dynasty":"唐","verses":["除却闲吟外，人间事事慵。","更深成一句，月冷上孤峰。","穷理多瞑目，含毫静倚松。","终篇浑不寐，危坐到晨钟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-fd54e990-4f28-4d16-9cbd-1ce909e3247a","tags":[]},{"id":"poem-1e65cab9109bfc93f979bb58","title":"送维谅上人归洞庭","author":"皎然","dynasty":"唐","verses":["从来湖上胜人间，远爱浮云独自还。","孤月空天见心地，寥寥一水镜中山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6aa24cb9-01be-4fbb-bee5-3d54ba38ffeb","tags":["洞庭湖"]},{"id":"poem-1e6a4427dc929480905cbcbf","title":"却到浙西","author":"李绅","dynasty":"唐","verses":["临平水竭蒹葭死，里社萧条旅馆秋。","尝叹晋郊无乞籴，岂忘吴俗共分忧。","野悲扬目称嗟食，林极翳桑顾所求。","苛政尚存犹惕息，老人偷拜拥前舟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1d5b8782-3afa-4a8b-8f97-acea92118d4e","tags":[]},{"id":"poem-1e80d213ad2ab22349aafe72","title":"终南望余雪","author":"祖咏","dynasty":"唐","verses":["终南阴岭秀，积雪浮云端。","林表明霁色，城中增暮寒。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b4780bd1-1703-4bce-a801-d5ed566826b5","tags":["唐诗三百首","写雪","冬天","写景","雪","冬","五言绝句"]},{"id":"poem-1e8401faa3ba76d0cb49ddef","title":"次韵苏子瞻题李公麟画马图","author":"苏颂","dynasty":"宋","verses":["霜纨横卷书縚垂，轴以瑇瑁囊青丝。","披图二妙骇人目，笔画劲利如刀锥。","龙媒迥出丹青手，势若飞动将奔驰。","鞯衔如在赤墀立，仆御犹纵红缨羁。","子虔六辔衒沃若，长康骏骨称天奇。","虽传画谱入神品，未有墨客评黄雌。","六诗形似到作者，三马意象能言之。","奇踪莫辨霸或干，高韵压倒陆与皮。","从来神物不常有，未遇真赏何人知。","君不见开元廏马四十万，作颂要须张帝师。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-6b4a68a3-462c-4509-b477-dd4f5caa4fc3","tags":[]},{"id":"poem-1e95f16fbf7ec34ebc03e8c2","title":"云阳馆与韩绅宿别","author":"司空曙","dynasty":"唐","verses":["故人江海别，几度隔山川。","乍见翻疑梦，相悲各问年。","孤灯寒照雨，湿竹暗浮烟。","更有明朝恨，离杯惜共传。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3138fe30-6cf6-45b0-a441-2d5398107a9a","tags":["唐诗三百首","友情","五言律诗","惜别"]},{"id":"poem-1e9806706e6bdace799e4fd8","title":"杂诗二首 一","author":"卢象","dynasty":"唐","verses":["家居五原上，征战是平生。","独负山西勇，谁当塞下名。","死生辽海战，雨雪蓟门行。","诸将封侯尽，论功独不成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5be96530-0656-42e0-bf69-a0c7a9c73a58","tags":[]},{"id":"poem-1e98374dd7caa9780551ae6a","title":"摊破浣溪沙·欲语心情梦已阑","author":"纳兰性德","dynasty":"清","verses":["欲语心情梦已阑，镜中依约见春山。","方悔从前真草草，等闲看。","环佩只应归月下，钗钿何意寄人间。","多少滴残红蜡泪，几时干。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-38","tags":[]},{"id":"poem-1ea35d14c54bd7218e1ece3a","title":"送刘侍御","author":"司空曙","dynasty":"唐","verses":["狱成收夜烛，整豸出登车。","黄叶辞荆楚，青山背汉初。","早朝新羽衞，晚下步徒胥。","应念长沙谪，思乡不食鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3ca822a6-8abd-42b0-a0cd-d38e81e22fb0","tags":[]},{"id":"poem-1ebcb1751285fa3b75d52e5e","title":"归朝欢·别岸扁舟三两只","author":"柳永","dynasty":"宋","verses":["别岸扁舟三两只。","葭苇萧萧风淅淅。","沙汀宿雁破烟飞，溪桥残月和霜白。","渐渐分曙色。","路遥山远多行役。","往来人，只轮双桨，尽是利名客。","一望乡关烟水隔。","转觉归心生羽翼。","愁云恨雨两牵萦，新春残腊相催逼。","岁华都瞬息。","浪萍风梗诚何益。","归去来，玉楼深处，有个人相忆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-98","tags":[]},{"id":"poem-1ec22348adc37cf71b4dbcb7","title":"月夜舟中","author":"戴复古","dynasty":"宋","verses":["满船明月浸虚空，绿水无痕夜气冲。","诗思浮沈樯影里，梦魂摇拽橹声中。","星辰冷落碧潭水，鸿雁悲鸣红蓼风。","数点渔灯依古岸，断桥垂露滴梧桐。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-月夜舟中","tags":[]},{"id":"poem-1ed3b5e14bfb046c3fd63aab","title":"交河塞下曲","author":"胡曾","dynasty":"唐","verses":["交河冰薄日迟迟，汉将思家感别离。","塞北草生苏武泣，陇西云起李陵悲。","晓侵雉堞乌先觉，春入关山雁独知。","何处疲兵心最苦，夕阳楼上笛声时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c0bd863f-b9ef-4cfa-bd67-f67b817fd7c4","tags":[]},{"id":"poem-1ed5b027490aad56324c444e","title":"同群公题张处士菜园","author":"高适","dynasty":"唐","verses":["耕地桑柘间，地肥菜常熟。","为问葵藿资，何如庙堂肉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7a466652-6517-480e-aad3-2d5e4df247be","tags":[]},{"id":"poem-1eda739e50d493358904954e","title":"同前","author":"萧德祥《小孙屠》","dynasty":"元","verses":["今日除名字，皆是我恩德。","(旦)人非土木的，不敢忘恩义。","(和)幸然脱得花门去，心欢喜鸳鸯情，免沉迷。","如花貌，绝风雨(外)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8592","tags":[]},{"id":"poem-1ee0427dad3118c3aa54c391","title":"送朴山人归新罗","author":"马戴","dynasty":"唐","verses":["浩渺行无极，扬帆但信风。","云山过海半，乡树入舟中。","波定遥天出，沙平远岸穷。","离心寄何处，目断曙霞东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2ecf0c47-b59c-46ea-8360-1402ac4719c8","tags":[]},{"id":"poem-1ef12cda5d7ffa599e936d58","title":"又和南园真率会见赠","author":"司马光","dynasty":"宋","verses":["白头难入少年场，林下相招莫笑狂。","绿筿影侵棋局暗，黄梅花渍酒卮香。","任真自愧殽羞薄，假寐初便枕箪凉。","酬应诗豪困牵率，从来懒放似稽康。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-7b449e98-040e-4083-a281-2ec2b929f369","tags":[]},{"id":"poem-1efa5cecacb8a8cdfad6ff8e","title":"咏史诗 马陵","author":"胡曾","dynasty":"唐","verses":["坠叶萧萧九月天，驱兵独过马陵前。","路傍古木虫书处，记得将军破敌年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b5219034-d722-49ca-a440-76e9a3dbd72a","tags":[]},{"id":"poem-1eff82c9cb2688c1e5df21a3","title":"同前","author":"萧德祥《小孙屠》","dynasty":"元","verses":["谁知命运遭乖蹇，今朝受刑宪。","免教受扌朋扒，感恩即非浅。","(和同前)(净)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8645","tags":[]},{"id":"poem-1f0977c50f220fea1c77c3d6","title":"敦煌廿咏（并序） 九、瑟瑟咏[二○]","author":"敦煌人作品[一]","dynasty":"唐","verses":["瑟瑟焦山下，悠悠采几年。","为珠悬宝髻[二一]，作璞间金钿。","色入青霄里，光浮黑碛边。","世人偏重此，谁念楚材贤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c6fc1403-cc00-4c66-8f59-4b030005dd9f","tags":[]},{"id":"poem-1f1afddd8dc23ee4adb091fe","title":"句","author":"李侍御","dynasty":"唐","verses":["尽日不归花路晚，绿杨楼下醉如泥。","月上西陵千里阔，渔舟夜火隔沙明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-40a659c0-3ae2-4bbe-b9ab-7bb019b8a895","tags":[]},{"id":"poem-1f1c214cf623a4e45efb8559","title":"探春令","author":"无名氏《张协状元》","dynasty":"元","verses":["三年一度选英贤，论学业非浅。","(后出接)又未知，谁氏登鳌首？甚日满奴心愿？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2601","tags":[]},{"id":"poem-1f1ef49bdde837d5244bc418","title":"别卢纶","author":"畅当","dynasty":"唐","verses":["故交君独在，又欲与君离。","我有新秋泪，非关宋玉悲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c32bc3e0-3733-4816-b56d-9c72a0e20119","tags":[]},{"id":"poem-1f22119e2b84a98d3ddf1f82","title":"寄山中伉禅师","author":"贯休","dynasty":"唐","verses":["举世遭心使，吾师独使心。","万缘冥目尽，一句不言深。","野火烧禅石，残霞照栗林。","秋风溪上路，终愿一相寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-01b15546-2895-456b-81eb-459360c705f8","tags":[]},{"id":"poem-1f23eb6279cafeb427fbf499","title":"和晋陵陆丞早春游望","author":"杜审言","dynasty":"唐","verses":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光转绿苹。","忽闻歌古调，归思欲沾巾。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b881b056-6d92-45e8-9620-4710a375776f","tags":["春天","唐诗三百首","伤怀","和诗","思乡","五言律诗"]},{"id":"poem-1f294dc26d3b2e991e50f695","title":"贺知章官至秘书监镜湖山水上疏明皇放归乡土仍赐镜湖山河五百里曹松题镜湖诗曰","author":"曹松","dynasty":"唐","verses":["小因良匠写清光，照见越州年岁长。","裹许云山更孤峭，一时宣赐贺知章。","（见《永乐大典》卷二二六七「六模」「湖」字「镜湖」条〖二函二十册〗。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-71c12197-8a1f-4454-99ad-0f37ee5965ae","tags":[]},{"id":"poem-1f2950bbde727f0a353772bd","title":"古意","author":"张碧","dynasty":"唐","verses":["銮舆不碾香尘灭，更残三十六宫月。","手持纨扇独含情，秋风吹落横波血。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ec20615e-d3da-4109-b0f3-f754488e7b42","tags":[]},{"id":"poem-1f2d1af209cd5d63077c037f","title":"赠从弟谷","author":"刘得仁","dynasty":"唐","verses":["此世荣枯岂足惊，相逢惟要眼长青。","从来不爱三闾死，今日凭君莫独醒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-917638b9-f60e-4f06-adba-4b2564f8657c","tags":[]},{"id":"poem-1f35ae2ed7f9be1af6aa713a","title":"好花儿","author":"施惠《幽闺记》","dynasty":"元","verses":["(众)恨不得掘地翻天，见树边一人端然，是个土地公公塑在花园。","许金钱，望指点，。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2882","tags":[]},{"id":"poem-1f3af26ab286af201eada9fd","title":"宣州谢朓楼饯别校书叔云","author":"李白","dynasty":"唐","verses":["弃我去者昨日之日不可留，乱我心者今日之日多烦忧。","长风万里送秋雁，对此可以酣高楼。","蓬莱文章建安骨，中间小谢又清发。","俱怀逸兴壮思飞，欲上青天览日月。","抽刀断水水更流，举杯销愁愁更愁。","人生在世不称意，明朝散发弄扁舟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-5593d522-b820-4c06-bab6-0ab5a0fc1d46","tags":["唐诗三百首","八年级下册(课外)","七言古诗","初中古诗","哲理","离别","抒怀","水","豪迈"]},{"id":"poem-1f3db741d3754ee8b4809e13","title":"酒泉子·绿树春深","author":"毛文锡","dynasty":"五代","verses":["绿树春深，燕语莺啼声断续。","蕙风飘荡入芳丛，惹残红。","柳丝无力袅烟空，金盏不辞须满酌。","海棠花下思朦胧，醉香风。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-6","tags":[]},{"id":"poem-1f47985199e4bc83c64e4a33","title":"八拍蛮·孔雀尾拖金线长","author":"孙光宪","dynasty":"五代","verses":["孔雀尾拖金线长，怕人飞起入丁香。","越女沙头争拾翠，相呼归去背斜阳。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-32","tags":[]},{"id":"poem-1f4afc37f4bcab8c3243a9e8","title":"为李魏公赋谢汧公","author":"司空曙","dynasty":"唐","verses":["白雪高吟际，青霄远望中。","谁言路遐旷，宫征暗相通。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d8474ce5-372b-49a0-bdf2-0fe91fdd5c73","tags":[]},{"id":"poem-1f4bac024a2b0eda86b3830c","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["闻道是关西，老将太尉。","(净)本不敢，直入来谒见，托在同官，又是亲戚。","请郡主出来这里，听洒拜启，休要致疑。","(合同前)(旦出)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2730","tags":[]},{"id":"poem-1f55fcce4109c69f59b3acff","title":"赠陈长史妓","author":"刘言史","dynasty":"唐","verses":["宝钿云和玉禁僊，深含媚靥褭朱弦。","春风不怕君王恨，引出幽花落外边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1932761b-ac2a-4046-9604-240eb2c07e71","tags":[]},{"id":"poem-1f574862effb3c0fe22198e2","title":"哭李进士","author":"赵嘏","dynasty":"唐","verses":["牵马街中哭送君，灵车辗雪隔城闻。","唯有山僧与樵客，共舁孤榇入幽坟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3c286345-cf35-410e-b8b4-e95a51466009","tags":[]},{"id":"poem-1f5839eece2e814861713b48","title":"浣溪沙·雨歇梧桐泪乍收","author":"纳兰性德","dynasty":"清","verses":["雨歇梧桐泪乍收，遣怀翻自忆从头。","摘花销恨旧风流。","帘影碧桃人已去，屧痕苍藓径空留。","两眉何处月如钩。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-134","tags":[]},{"id":"poem-1f6eaf132de794c108cfac58","title":"恨春迟·欲借江梅荐饮","author":"欧阳修","dynasty":"宋","verses":["欲借江梅荐饮。","望陇驿、音息沈沈。","住在柳州东，彼此相思，梦回云去难寻。","归燕来时花期浸。","淡月坠、将晓还阴。","争奈多情易感，风信无凭，如何消遣初心。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-812","tags":[]},{"id":"poem-1f74b04dd4aea28b915215cd","title":"扬州慢·淮左名都","author":"姜夔","dynasty":"宋","verses":["淮左名都，竹西佳处，解鞍少驻初程。","过春风十里，尽荠麦青青。","自胡马窥江去后，废池乔木，犹厌言兵。","渐黄昏，清角吹寒，都在空城。","杜郎俊赏，算而今，重到须惊。","纵豆蔻词工，青楼梦好，难赋深情。","二十四桥仍在，波心荡、冷月无声。","念桥边红药，年年知为谁生。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-132","tags":["宋词三百首"]},{"id":"poem-1f76632fffc236de4b28002f","title":"江行无题一百首 十一","author":"钱珝","dynasty":"唐","verses":["夜江清未晓，徒惜月光沉。","不是因行乐，堪伤老大心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e68cb702-b6a6-401a-a1ae-98228a2d566f","tags":[]},{"id":"poem-1f862bba89ead37eaac983ad","title":"虞美人·严陵滩畔香醪好","author":"葛胜仲","dynasty":"宋","verses":["严陵滩畔香醪好。","遮莫东方晓。","春风盎盎如寒肌。","人道霜浓腊月、我还疑。","红炉火热香围坐。","梅蕊迎春破。","一声清唱解人颐。","人道牢愁千斛、我谁知。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-23","tags":[]},{"id":"poem-1f8ae221e88c78c99cb2838d","title":"送羊侯因简崔帅一首","author":"陈造","dynasty":"宋","verses":["游宦何许佳，解印还故乡。","旧国仍旧都，别去未始忘。","一旦吾眼中，怡然得徜徉。","钓处它日梁，树是儿时桑。","扶携拥道周，老倪皆壶浆。","官簿有高下，此乐均未央。","羊侯万金将，文武擅两长。","棱威肃貔虎，谈兵厉冰霜。","小作漳滨卧，斗饭方健强。","胡为倚秋风，归思歌慨慷。","似闻山阳郊，迓者立堵墙。","湖蟹九月肥，社酒千室香。","海舶来麋䴥，江户送鳟鲂。","举白作鲸吸，罗幙同春阳。","乐事有如此，夙志今始偿。","我袖如椽笔，落纸烟云翔。","自今小昼锦，为君记新堂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-72508e3f-53c0-4486-8a3d-b4812916cd94","tags":[]},{"id":"poem-1f8afa763f88958e606912a5","title":"采桑子·樱桃著子如红豆","author":"黄庭坚","dynasty":"宋","verses":["樱桃著子如红豆，不管春归。","闻道开时。","蜂惹香须蝶惹衣。","楼台灯火明珠翠，酒恋歌迷。","醉玉东西。","少个人人暖被携。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-788","tags":[]},{"id":"poem-1fa87458759c97a554e5019e","title":"游长宁公主流杯池二十五首 四","author":"上官昭容","dynasty":"唐","verses":["仰循茅宇，俯眄乔枝。","烟霞问讯，风月相知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f696fcf6-52a5-4637-bf2e-0feda4325bc6","tags":[]},{"id":"poem-1fc4db38ad47e38568251803","title":"次韵王省干  其三","author":"陈造","dynasty":"宋","verses":["王侯文振奇，人作高山仰。","世学方波颓，渠独不流荡。","诸生畏雄骜，六艺厚涵养。","遥知落诗笔，高像寄逸想。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-50affd9d-cdcc-42dc-9d5c-a9c2bacd0d49","tags":[]},{"id":"poem-1fcadc7c7d93735beca0b44e","title":"奉和御制夏中垂钓作","author":"徐铉","dynasty":"宋","verses":["物茂时平日正长，翠华停驭睠方塘。","文竿乍拂圆荷动，頳尾时翻素荇香。","睿赏只应从暇豫，圣恩宁肯间沉翔。","吞舟自是贪芳饵，犹笑成汤一面张。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2d5ac908-8d32-4792-af86-aada58fc5470","tags":[]},{"id":"poem-1fdcbfefe3dcba6ec483d5f3","title":"真玉堂作","author":"洪咨夔","dynasty":"宋","verses":["禁门深锁寂无哗，浓墨淋漓两相麻。","唱彻五更天未晓，一墀月浸紫薇花。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-真玉堂作","tags":[]},{"id":"poem-1fe32c33c3b0fd5eea6668e6","title":"旧镜","author":"鲍溶","dynasty":"唐","verses":["婵娟本家镜，与妾归君子。","每忆并照时，相逢明月里。","春风忽分影，白日难依倚。","珠粉不结花，玉珰宁辉耳。","心期不可见，不保长如此。","华发一欺人，青铜化为鬼。","良人有归日，肯学妖桃李。","瑶匣若浮云，冥冥藏玉水。","侍儿不遣照，恐学孤鸾死。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9015befa-d621-4ca8-a533-9412338bb0f3","tags":[]},{"id":"poem-1fe985935b2ac9d46834431e","title":"太常引·自题小照","author":"纳兰性德","dynasty":"清","verses":["西风乍起峭寒生，惊雁避移营。","千里暮云平，休回首、长亭短亭。","无穷山色，无边往事，一例冷清清。","试倩玉萧声，唤千古、英雄梦醒。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-40","tags":[]},{"id":"poem-1fee60a8794adc41debffd78","title":"西溪子·金缕翠钿浮动","author":"李珣","dynasty":"五代","verses":["金缕翠钿浮动，妆罢小窗圆梦。","日高时，春已老，人来到，满地落花慵扫。","无语倚屏风，泣残红。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-46","tags":[]},{"id":"poem-1ff0b3a881b673b63cf9f715","title":"河传·燕飏","author":"顾敻","dynasty":"五代","verses":["燕飏，晴景。","小窗屏暖，鸳鸯交颈。","菱花掩却翠鬓欹，慵整。海棠帘外影。","绣帷香断金㶉𫛶，无消息，心事空相忆。","倚东风，春正浓。","愁红，泪痕衣上重。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-39","tags":[]},{"id":"poem-1ff251e4048fb11169bd7e7c","title":"同前换头","author":"萧德祥《小孙屠》","dynasty":"元","verses":["欢聚。","草嫩轻黄，弄丝丝暗织，素肠千缕。","夭桃张锦，无烟禁火烧拔。","凝觑，万卉争开春罗绮，步芳郊真得趣。","(和同前)(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8565","tags":[]},{"id":"poem-1fffe36c2207c909cab0fd66","title":"谒李尊师","author":"奚贾","dynasty":"唐","verses":["万物返常性，惟道贵自然。","先生容其微，隐几为列仙。","炼魄闭琼户，养毛飞洞天。","将知逍遥久，得道无岁年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ac8e5604-8985-4de3-bc4a-2904364dcfe9","tags":[]},{"id":"poem-200001e0be3038f8b252f0a5","title":"应制贺边军支春衣 一","author":"柳公权","dynasty":"唐","verses":["去岁虽无战，今年未得归。","皇恩何以报，春日得春衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-90926ca1-f8e1-4833-a322-9a81e43ab878","tags":[]},{"id":"poem-2000cf41855d582803411beb","title":"天仙子·水调数声持酒听","author":"张先","dynasty":"宋","verses":["水调数声持酒听。","午醉醒来愁未醒。","送春春去几时回，临晚镜。","伤流景。","往事后期空记省。","沙上并禽池上暝。","云破月来花弄影。","重重帘幕密遮灯，风不定。","人初静。","明日落红应满径。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-156","tags":["宋词三百首"]},{"id":"poem-200135ceab7244bf8417c5c8","title":"咏乌代陈师道","author":"太宗皇帝","dynasty":"唐","verses":["凌晨丽城去，薄暮上林栖。","辞枝枝暂起，停树树还低。","向日终难托，迎风讵肯迷。","只待纤纤手，曲里作宵啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-2b4fdd33-abbc-4c1b-a33e-4e786e544865","tags":[]},{"id":"poem-200152e39c043188317478b5","title":"菩萨蛮·晶帘一片伤心白","author":"纳兰性德","dynasty":"清","verses":["晶帘一片伤心白，云鬟香雾成遥隔。","无语问添衣，桐阴月已西。","西风鸣络纬，不许愁人睡。","只是去年秋，如何泪欲流。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-60","tags":[]},{"id":"poem-2001927c6fca19a58fa52344","title":"武威同诸公过杨七山人得藤字","author":"高适","dynasty":"唐","verses":["幕府日多暇，田家岁复登。","相知恨不早，乘兴乃无恒。","穷巷在乔木，深斋垂古藤。","边城唯有醉，此外更何能。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-655ae29b-c115-4b27-a0b8-caa7e01d1808","tags":[]},{"id":"poem-2007b1c94b040f382b5b9a68","title":"最能行","author":"杜甫","dynasty":"唐","verses":["峡中丈夫绝轻死，少在公门多在水。","富豪有钱驾大舸，贫穷取给行艓子。","小儿学问止论语，大儿结束随商旅。","攲帆侧柁入波涛，撇漩捎𣸣无险阻。","朝发白帝暮江陵，顷来目击幸有征。","瞿堂漫天虎须怒，归州长年行最能。","此乡之人气量窄，误竞南风疎北客。","若道土无英俊才，何得山有屈原宅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-bbbbba72-14ae-42d1-9f5a-09a077f2d0c6","tags":[]},{"id":"poem-2009c96da582fa04cd71f00f","title":"鲍老催","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["意深爱笃，文章富贵珠万斛，天教艳质为眷属。","似蝶恋花，凤栖梧，鸾停竹。","男儿有书须勤读，书中自黄金屋，也自有千钟粟。","(合唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5066","tags":[]},{"id":"poem-200ba85c33ea14c7e75d9500","title":"江陵孝女","author":"张籍","dynasty":"唐","verses":["孝女独垂发，少年唯一身。","无家空托墓，主祭不从人。","相吊有行客，起庐无旧邻。","江头闻哭处，寂寂楚花春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-febead0e-6183-478c-88a5-bf9ef073d3ac","tags":[]},{"id":"poem-200c2b2c905c2b78c17a6ca0","title":"送韦向睦州谒独孤使君汜","author":"皎然","dynasty":"唐","verses":["才子南看多远情，闲舟荡漾任春行。","新安江色长如此，何似新安太守清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-76f65785-3e98-4acc-a7f8-5c6cc6388ec9","tags":[]},{"id":"poem-202493addf3097e197f2c936","title":"菩萨蛮·风庭瑟瑟灯明灭","author":"李弥逊","dynasty":"宋","verses":["风庭瑟瑟灯明灭。","碧梧枝上蝉声歇。","枕冷梦魂惊。","一阶寒水明。","鸟飞人未起。","月露清如洗。","无语听残更。","愁从两鬓生。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-16","tags":[]},{"id":"poem-2024a26ae3343d040ac98892","title":"范真传侍御累有寄因奉酬十首 一","author":"鲍溶","dynasty":"唐","verses":["昨日新花红满眼，今朝美酒绿留人。","更宜明月含芳露，凭仗萧郎夜赏春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-07ff702e-afa1-4580-a6cd-edd5c07cad60","tags":[]},{"id":"poem-2025c9add3cd3b5f3a7d58ab","title":"敦煌（伯五○○七）三首 仆固天王干符三年四月廿四日打破伊州……（此缺数字）录打劫酒泉后却□断（下缺）","author":"敦煌人作品[一]","dynasty":"唐","verses":["为言回鹘倚凶（下缺）（〖1〗以上诗三首，都作于唐大中二年〖公元八四八年〗张义潮起义以后。","「歌谣再复归唐国」，即咏此事。","第三首诗题有历史价值。","仆固天王殆即北庭廻鹘首领仆固俊。","此诗应是当时当地人所作，所以称他为「天王」。","干符三年〖八七六〗打破伊州事，不见史书记载。","可惜诗题残缺，诗文仅存六字，以致意义不够明显。","这时候，仆固俊受张义潮的指挥，打败了吐蕃不久。","这次〖八七六〗打伊州，想他是受张义潮的命令的。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-417d296f-52cb-49b9-8419-ef18c9b6ea3e","tags":[]},{"id":"poem-20304447e1eb4a7911d0289f","title":"风不鸣条","author":"姚鹄","dynasty":"唐","verses":["吾君理化清，上瑞报时平。","晓吹何曾歇，柔条自不鸣。","花香知暗度，柳动觉潜生。","只见低垂影，那闻击触声。","大王初溥畅，少女正轻盈。","幸遇无私力，幽芳愿发荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-217e20a4-f217-4632-9c40-8783c5be5eab","tags":[]},{"id":"poem-203d1d527b1cd746d2c40363","title":"点绛唇·新月娟娟","author":"汪藻","dynasty":"宋","verses":["新月娟娟，夜寒江静山衔斗。","起来搔首。","梅影横窗瘦。","好个霜天，闲却传杯手。","君知否。","乱鸦啼后。","归兴浓于酒。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-266","tags":["宋词三百首"]},{"id":"poem-205d6477c529eeeee9939de7","title":"罗鼓令","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我终朝的受馁，你将来的饭怎吃？疾忙便抬，非干是我有些馋态。","(外唱)你看他衣衫都解，好茶饭将甚去买？婆婆，兀的是天灾，教他媳妇每难布摆。","(旦唱)婆婆息怒且休罪，待奴家一霎时却得再安排。","(合)思量到此，珠泪满腮。","看看做鬼，沟渠里埋。","纵然不死也难挨，教人只恨蔡伯喈。","(净唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5069","tags":[]},{"id":"poem-20724801818dac70c210d4ef","title":"座中走笔送前萧使君","author":"薛逢","dynasty":"唐","verses":["笙歌惨惨咽离筵，槐柳阴阴五月天。","未学苏秦荣佩印，却思平子赋归田。","芙蓉欲绽溪边蘂，杨柳初迷渡口烟。","自笑无成今老大，送君垂泪郭门前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-aa45e9c6-4aff-400b-ba98-83b47165def2","tags":[]},{"id":"poem-2075e8ff3f6310afe078daaf","title":"浪淘沙·万叶战","author":"周邦彦","dynasty":"宋","verses":["万叶战，秋声露结，雁度砂碛。","细草和烟尚绿，遥山向晚更碧。","见隐隐、云边新月白。","映落照、帘幕千家，听数声何处倚楼笛。","装点尽秋色。","脉脉。","旅情暗自消释。","念珠玉、临水犹悲感，何况天涯客。","忆少年歌酒，当时踪迹。","岁华易老，衣带宽、懊恼心肠终窄。","飞散后、风流人阻，蓝桥约、怅恨路隔。","马蹄过、犹嘶旧巷陌。","叹往事、一一堪伤，旷望极。","凝思又把阑干拍。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-531","tags":[]},{"id":"poem-2084d7301759736527d5b7ea","title":"咏刀子","author":"张𬸦","dynasty":"唐","verses":["自怜胶漆重，相思意不穷。","不惜尖头物，终日在皮中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-16c79884-993e-4671-a9ef-70ad3782cea4","tags":[]},{"id":"poem-2089c9d7cb27ebab024dbb9c","title":"咏怀古迹五首 三","author":"杜甫","dynasty":"唐","verses":["群山万壑赴荆门，生长明妃尚有村。","一去紫台连朔漠，独留青冢向黄昏。","画图省识春风面，环佩空归月夜魂。","千载琵琶作胡语，分明怨恨曲中论。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3b5db620-1964-4674-a01d-ad70ba3ebd2a","tags":["唐诗三百首","隋・唐・五代","七言律诗","怀古","思乡"]},{"id":"poem-208d4752408f0cde3b3fe722","title":"踏莎行·燕燕轻盈","author":"姜夔","dynasty":"宋","verses":["燕燕轻盈，莺莺娇软。","分明又向华胥见。","夜长争得薄情知，春初早被相思染。","别后书辞，别时针线。","离魂暗逐郎行远。","淮南皓月冷千山，冥冥归去无人管。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-124","tags":["宋词三百首"]},{"id":"poem-208ec8a7a4be4dd43a339568","title":"高司马移竹","author":"马戴","dynasty":"唐","verses":["丛居堂下幸君移，翠掩灯窗露叶垂。","莫羡孤生在山者，无人看著拂云枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e40d606c-4c5f-4217-a0e4-939aee655c0a","tags":[]},{"id":"poem-209be4d1fa9386dd25f3cd14","title":"蒿里行","author":"曹操","dynasty":"汉","verses":["关东有义士，兴兵讨群凶。","初期会盟津，乃心在咸阳。","军合力不齐，踌躇而雁行。","势利使人争，嗣还自相戕。","淮南弟称号，刻玺于北方。","铠甲生虮虱，万姓以死亡。","白骨露于野，千里无鸡鸣。","生民百遗一，念之断人肠。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-6","tags":[]},{"id":"poem-209c98c3d4ea835c57e6965e","title":"题甘露寺","author":"曹松","dynasty":"唐","verses":["香门接巨垒，画角间清钟。","北固一何峭，西僧多此逢。","天垂无际海，云白久晴峰。","旦暮然灯外，涛头振蛰龙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-bf35e867-fc2c-4bee-9587-c0e55c19a102","tags":[]},{"id":"poem-20a2f52a81c0f84442ff2af8","title":"菊花新","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["封书自远到亲闱，又见关河朔雁飞。","梧叶满庭除，还如我闷怀堆积。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5167","tags":[]},{"id":"poem-20a5b76ec87817a09066230d","title":"同题仙游观","author":"韩翃","dynasty":"唐","verses":["仙台下见五城楼，风物凄凄宿雨收。","山色遥连秦树晚，砧声近报汉宫秋。","疎松影落空坛静，细草香闲小洞幽。","何用别寻方外去，人间亦自有丹丘。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b411ce1e-ac09-4427-ab32-f8dc7a57e566","tags":["唐诗三百首","向往","七言律诗","游历"]},{"id":"poem-20a62c8da4b601afccf68310","title":"虞美人","author":"无名氏《张协状元》","dynasty":"元","verses":["缉麻缉苎攻针指，亦是不得已。","时常眼泪不曾干，只恐别郎容易见郎难。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2594","tags":[]},{"id":"poem-20ad9c552843637a494e209e","title":"秋夜次四姪韵五首  其一","author":"刘跂","dynasty":"宋","verses":["凉飔起天末，倏已扫庭户。","光鲜向时柳，惨淡非其故。","铅华不足恃，美人抱幽素。","穷吾分当尔，不为读书误。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-2318ec71-3331-435f-b130-89faa6cb1a8e","tags":[]},{"id":"poem-20b22b83b6a67fc4bba9df89","title":"负薪行","author":"杜甫","dynasty":"唐","verses":["夔州处女发半华，四十五十无夫家。","更遭丧乱嫁不售，一生抱恨堪咨嗟。","土风坐男使女立，应当门户女出入。","十犹八九负薪归，卖薪得钱应供给。","至老双鬟只垂颈，野花山叶银钗竝。","筋力登危集市门，死生射利兼盐井。","面妆首饰杂啼痕，地褊衣寒困石根。","若道巫山女麤丑，何得此有昭君邨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7f4b9cac-65c4-42e8-949c-4dabc621de01","tags":[]},{"id":"poem-20ba28b7443916e4964d212e","title":"六言颂六首赠安国觉老  其三","author":"李纲","dynasty":"宋","verses":["本来滴水滴冻，岂碍彻风彻颠。","欲问东西祖意，莫嫌吃饭参禅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-adebf365-2456-4162-9417-4a08cded7742","tags":[]},{"id":"poem-20bee5963884e0c369e13e46","title":"采蘩","author":"佚名","dynasty":"先秦","verses":["于以采蘩？于沼于沚。于以用之？公侯之事。","于以采蘩？于涧之中。于以用之？公侯之宫。","被之僮僮，夙夜在公。被之祁祁，薄言还归。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-12","tags":[]},{"id":"poem-20dbbad822291254a9c3c8fa","title":"甘州子·一炉龙麝锦帷旁","author":"顾敻","dynasty":"五代","verses":["一炉龙麝锦帷旁，屏掩映，烛荧煌。","禁楼刁斗喜初长，罗荐绣鸳鸯。","山枕上，私语口脂香。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-41","tags":[]},{"id":"poem-20ea1600051f074bf7c871c4","title":"胡笳十八拍 第一拍","author":"李纲","dynasty":"宋","verses":["四海十年不解兵，朝降夕叛幽蓟城。","杀气南行动天轴，犬戎也复临咸京。","铁马长鸣不知数，虏骑凭陵杂风雨。","自是君王未备知，一生长恨奈何许。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3f07da6b-2e85-4745-ae53-7785bcf140bc","tags":[]},{"id":"poem-20ea67582e217dba056cce4d","title":"渭阳","author":"佚名","dynasty":"先秦","verses":["我送舅氏，曰至渭阳。何以赠之？路车乘黄。","我送舅氏，悠悠我思。何以赠之？琼瑰玉佩。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-133","tags":[]},{"id":"poem-20ebb17c4310821754a3f3c8","title":"南海子·红桥夹岸柳平分","author":"纳兰性德","dynasty":"清","verses":["红桥夹岸柳平分，雉兔年年不掩群。","飞放何须烦海户，郊南新置羽林军。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-230","tags":[]},{"id":"poem-20ed6bafeaaf08394a5c7d44","title":"鹧鸪天·莫问甘醪浊与清","author":"洪适","dynasty":"宋","verses":["莫问甘醪浊与清。","试将一酌破愁城。","海棠过后荼蘼发，堪叹人间不再生。","心已老，眼重明。","嫣然国色带朝酲。","耳边听得兰亭曲，一咏流觞已有名。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-741","tags":[]},{"id":"poem-20f25a3ea632c9282d88a5d7","title":"舞曲歌辞 凯乐歌辞 君臣同庆乐","author":"不详","dynasty":"唐","verses":["主圣开昌历，臣忠奉大猷。","君看偃革后，便是太平秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5fe98de1-5cd1-4a24-892c-56e058583719","tags":[]},{"id":"poem-20fbbf694b5a2768b3fde0cd","title":"行路难三首 二","author":"李白","dynasty":"唐","verses":["大道如青天，我独不得出。","羞逐长安社中儿，赤鸡白狗赌梨栗。","弹劒作歌奏苦声，曳裾王门不称情。","淮阴市井笑韩信，汉朝公卿忌贾生。","君不见昔时燕家重郭隗，拥篲折节无嫌猜。","剧辛乐毅感恩分，输肝剖胆效英才。","昭王白骨萦烂草，谁人更扫黄金台。","行路难，归去来。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-801c3192-8001-4238-8ecf-0111f490e84c","tags":["乐府","失意","叹息","唐诗三百首"]},{"id":"poem-20fe20b9022b8b3881df107c","title":"梁谿四友赞序 粲华赞","author":"李纲","dynasty":"宋","verses":["我有佳友，粲粲其华。","金英炜煌，翠叶交加。","风露洒濯，色香相知。","宛如美人，象服逶迤。","可以忘忧，莫如旨酒。","泛此粲华，益我眉寿。","渊明一樽，子美三嗅。","永结清欢，相从白首。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-e8c1946d-eaf4-491a-a876-0e4d51e59715","tags":[]},{"id":"poem-20ff691c8fd237a06c551981","title":"郊庙歌辞 享太庙乐章 大顺舞","author":"郑𬘡","dynasty":"唐","verses":["於穆时文，受天明命。","允恭玄默，化成理定。","出震嗣德，应干传圣。","猗欤缉熙，千亿流庆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-27173453-b779-41af-a14b-aa21a44a4ecb","tags":[]},{"id":"poem-210029adb89c8b1d1d56cb2b","title":"八四","author":"王梵志","dynasty":"唐","verses":["忍辱生端正，多嗔作毒虵。","若人不儜恶，必得上三车。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c543c2b0-b82d-49a0-8061-98cc3a0d710e","tags":[]},{"id":"poem-210392c8e3e04bbd4cf2d76e","title":"汉宫春·春已归来","author":"辛弃疾","dynasty":"宋","verses":["春已归来，看美人头上，袅袅春幡。","无端风雨，未肯收尽馀寒。","年时燕子，料今宵、梦到西园。","浑未办、黄柑荐酒，更传青韭堆盘。","却笑东风从此，便薰梅染柳，更没些闲。","闲时又来镜里，转变朱颜。","清愁不断，问何人、会解连环。","生怕见、花开花落，朝来塞雁先还。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-217","tags":["宋词三百首"]},{"id":"poem-210cff5d04dcba949136b9ed","title":"宫怨二首 一","author":"柯崇","dynasty":"唐","verses":["尘满金炉不炷香，黄昏独自立重廊。","笙歌何处承恩宠，一一随风入上阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b26c5161-22f5-4a5f-b324-e9f2928a73e4","tags":[]}];
